const ico = (name) => {
  const t = document.createElement("template");
  const tech = TECH_ICONS[name];
  t.innerHTML = tech
    ? `<svg class="ico tech${tech[0] ? " tech-color" : ""}" viewBox="-12 -12 152 152" aria-hidden="true" data-tech="${name}"${tech[0] ? ` style="--brand:${tech[0]}"` : ""}>${tech[1].map((d) => `<path d="${d}" fill="currentColor"/>`).join("")}</svg>`
    : `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  return t.content.firstChild;
};
const setLabel = (el, name, text) => el.replaceChildren(ico(name), text);
const ib = (props, name, ...kids) => h("button", props, ico(name), ...kids);
for (const el of $$("[data-icon]")) el.prepend(ico(el.dataset.icon));

const wsURL = (path) => `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}${path}`;
const desktop = matchMedia("(min-width: 1024px)");

// Several computers can share this dashboard. Each runs its own Dash; the
// one serving this page forwards /peer/<name>/… to the others. A project's
// API calls go to the computer it lives on (its prefix); login, logout and
// the computer list always go to this one.
const HUB_ONLY = /^\/api\/(login|logout|me|machines|version|chat)\b/;
const here = () => state.project?.prefix || "";
const on = (prefix, path) => (HUB_ONLY.test(path) ? path : `${prefix}${path}`);

async function api(method, path, body, prefix = here()) {
  const res = await fetch(on(prefix, path), {
    method,
    headers: body ? { "Content-Type": "application/json" } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  if (res.status === 401) {
    location.replace("/login.html");
    throw new Error("Sign in again to continue.");
  }
  const ct = res.headers.get("content-type") || "";
  const data = ct.includes("json") ? await res.json() : await res.text();
  if (!res.ok) throw new Error(data.error || data || res.statusText);
  return data;
}

// ------------------------------------------------------------------ toasts & dialogs
const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)");
const EASE = "cubic-bezier(.2, .8, .2, 1)";

// leave() plays an exit animation (CSS class) before running done.
function leave(el, cls, done, ms = 180) {
  if (reduceMotion.matches) return done();
  el.classList.add(cls);
  setTimeout(() => { el.classList.remove(cls); done(); }, ms);
}

// toast(msg) for info, toast(msg, true) for errors, or toast(msg, { tone, head, action: { label, run } }).
// Hovering or focusing a toast pauses its countdown.
const TOAST_ICONS = { info: "bell", ok: "check", error: "x", review: "eye", approval: "flag", pr: "merge" };
function toast(msg, opts = {}) {
  if (typeof opts === "boolean") opts = { tone: opts ? "error" : "info" };
  const { tone = "info", head, action, icon = TOAST_ICONS[tone] || "bell" } = opts;
  const ms = opts.ms ?? (tone === "error" || action ? 7000 : 3500);
  let timer, start, left = ms, held = 0, gone = false;
  const close = () => { if (gone) return; gone = true; clearTimeout(timer); leave(t, "leaving", () => t.remove()); };
  const t = h("div", { class: `toast ${tone}`, role: tone === "error" ? "alert" : "status", style: `--ms: ${ms}ms` },
    h("span", { class: "toast-icon" }, ico(icon)),
    h("div", { class: "toast-body" }, head ? h("strong", {}, head) : null, msg ? h("span", {}, msg) : null),
    action ? h("button", { class: "toast-action", type: "button", onclick: () => { close(); attempt(action.run)(); } }, action.label) : null,
    ib({ class: "toast-close", type: "button", "aria-label": "Dismiss", title: "Dismiss", onclick: close }, "x"),
    h("span", { class: "toast-bar" }));
  const run = () => { start = Date.now(); timer = setTimeout(close, left); };
  const hold = () => { if (held++) return; clearTimeout(timer); left -= Date.now() - start; t.classList.add("held"); };
  const release = () => { if (--held) return; t.classList.remove("held"); run(); };
  t.addEventListener("pointerenter", hold);
  t.addEventListener("pointerleave", release);
  t.addEventListener("focusin", hold);
  t.addEventListener("focusout", release);
  const box = $("#toasts");
  box.append(t);
  while (box.children.length > 4) box.firstChild.remove();
  run();
}
const openTodo = (id) => ({ label: "Open", run: () => openDetail(id) });
const fail = (e) => toast(e.message || String(e), true);
const attempt = (fn) => async (...a) => { try { await fn(...a); } catch (e) { fail(e); } };

// Optional illustration; disappears if the image file isn't there.
function art(src, w, hgt) {
  const img = h("img", { class: "empty-art", src, alt: "", width: w, height: hgt, loading: "lazy", decoding: "async" });
  img.addEventListener("error", () => img.remove());
  return img;
}

async function copy(text, msg) {
  try {
    await navigator.clipboard.writeText(text);
    toast(msg);
  } catch {
    await ask({ title: "Copy this", body: text, ok: "Done" }); // clipboard needs https or localhost
  }
}

// ask() shows a confirmation or a text question as a sheet. Resolves to the
// entered text (or true), or null when cancelled.
function ask({ title, body = "", input = false, placeholder = "", ok = "OK", danger = false, attach = false }) {
  const d = $("#ask-sheet");
  $("#ask-attach").hidden = !attach;
  askAttach.reset();
  $("#ask-title").textContent = title;
  $("#ask-body").textContent = body;
  $("#ask-body").hidden = !body;
  const field = $("#ask-input");
  field.hidden = !input;
  field.value = "";
  field.placeholder = placeholder;
  const okBtn = $("#ask-ok");
  setLabel(okBtn, danger ? "trash" : "check", ok);
  okBtn.className = `btn ${danger ? "danger" : "primary"}`;
  d.returnValue = "";
  d.showModal();
  if (input) field.focus();
  return new Promise((resolve) => {
    d.addEventListener("close", () => {
      if (d.returnValue !== "ok") return resolve(null);
      if (attach) return askAttach.settled().then(() => resolve({ text: field.value.trim(), attachments: askAttach.ids() }));
      resolve(input ? field.value.trim() : true);
    }, { once: true });
  });
}

// ------------------------------------------------------------------ attachments
// Screenshots and files for Claude: an "Attach file" button, paste into the
// text field, or drop onto the sheet.
const CLIP = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 11.5 12.6 19.9a5 5 0 0 1-7.1-7.1l8.5-8.5a3.3 3.3 0 0 1 4.7 4.7l-8.5 8.5a1.7 1.7 0 0 1-2.4-2.4l7.8-7.8" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const clip = () =>h("span", { class: "clip", innerHTML: CLIP });
const uploadURL = (a, prefix = here()) => on(prefix, `/api/uploads/${a.id}/${encodeURIComponent(a.name)}`);
const ACCEPT = "image/png,image/jpeg,image/gif,image/webp,image/svg+xml,.pdf,.txt,.md,.log,.json,.csv";

async function uploadFile(file, prefix = here()) {
  const res = await fetch(on(prefix, `/api/uploads?name=${encodeURIComponent(file.name || "pasted")}`), {
    method: "POST", body: file, headers: { "Content-Type": file.type || "application/octet-stream" },
  });
  if (res.status === 401) { location.replace("/login.html"); throw new Error("Sign in again to continue."); }
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || res.statusText);
  return data;
}

function attachThumb(a, onRemove, prefix = here()) {
  const isImg = a.type.startsWith("image/");
  return h("span", { class: "chip" },
    h("a", { class: "chip-link", href: uploadURL(a, prefix), target: "_blank", rel: "noopener", title: a.name },
      isImg ? h("img", { src: uploadURL(a, prefix), alt: "", loading: "lazy" }) : h("span", { class: "chip-icon" }, (a.name.split(".").pop() || "file").toUpperCase()),
      h("span", { class: "chip-name" }, a.name)),
    onRemove ? h("button", { type: "button", class: "chip-x", "aria-label": `Remove ${a.name}`, onclick: onRemove }, "×") : null);
}

// compact (the chat composers) drops the button and hides the row while it's
// empty; files arrive by paste or drop onto zone. prefix names the computer
// that stores the uploads.
function attachBox(el, textarea, onChange = () => {}, { zone = el.closest("dialog") || el, compact = false, prefix = here } = {}) {
  let items = [], pending = 0, busy = Promise.resolve();
  const input = h("input", { type: "file", accept: ACCEPT, multiple: true, hidden: true, onchange: () => { add(input.files); input.value = ""; } });
  const render = () => {
    if (compact) el.hidden = !items.length && !pending;
    el.replaceChildren(
      ...items.map((a) => attachThumb(a, () => { items = items.filter((x) => x !== a); render(); onChange(); }, prefix())),
      ...(pending ? [h("span", { class: "chip uploading" }, h("span", { class: "spinner", "aria-hidden": "true" }), `Uploading ${pending}…`)] : []),
      ...(compact ? [] : [h("button", { type: "button", class: "btn small attach-btn", onclick: () => input.click() },
        clip(),
        "Attach file"),
      input]));
  };
  const off = () => !compact && el.hidden;
  const add = (files) => {
    files = [...files];
    if (!files.length) return;
    pending += files.length;
    render();
    const at = prefix();
    busy = busy.then(async () => {
      for (const f of files) {
        try { items.push(await uploadFile(f, at)); onChange(); } catch (e) { fail(e); }
        pending--;
        render();
      }
    });
  };
  textarea?.addEventListener("paste", (e) => {
    const files = [...(e.clipboardData?.files || [])];
    if (files.length) { e.preventDefault(); add(files); }
  });
  zone.addEventListener("dragover", (e) => {
    if (off() || !e.dataTransfer?.types.includes("Files")) return;
    e.preventDefault();
    zone.classList.add("file-over");
  });
  zone.addEventListener("dragleave", (e) => { if (!zone.contains(e.relatedTarget)) zone.classList.remove("file-over"); });
  zone.addEventListener("drop", (e) => {
    zone.classList.remove("file-over");
    if (off() || !e.dataTransfer?.files.length) return;
    e.preventDefault();
    add(e.dataTransfer.files);
  });
  render();
  return {
    reset(list = []) { items = [...list]; pending = 0; render(); },
    ids: () => items.map((a) => a.id),
    items: () => [...items],
    settled: () => busy,
  };
}
const todoAttach = attachBox($("#todo-attach"), $("#todo-form").prompt, () => draft.changed());
const promptEditor = mdEditor($("#todo-form").prompt);

// The todo form autosaves to this browser while you type; reopening the
// form (even after a reload or a crash) brings the draft back.
const draftKey = (t) => `${projectKey(state.project)}/${t?.id || "new"}`;
const draft = drafts({
  read() {
    const f = $("#todo-form");
    return { title: f.title.value, prompt: f.prompt.value, goal: f.goal.checked, priority: f.priority.value, attachments: todoAttach.items() };
  },
  write(d) {
    const f = $("#todo-form");
    f.title.value = d.title ?? "";
    f.prompt.value = d.prompt ?? "";
    f.goal.checked = !!d.goal;
    f.priority.value = d.priority ?? 0;
    todoAttach.reset(d.attachments || []);
    promptEditor.render();
  },
  onStatus(st, at) {
    const el = $("#todo-draft");
    if (st === "typing") return;
    el.dataset.state = st;
    if (st === "saved") { el.replaceChildren("Draft saved on this device"); return; }
    if (st === "restored") {
      el.replaceChildren(`Restored your unsaved draft from ${ago(new Date(at).toISOString()) === "now" ? "just now" : `${ago(new Date(at).toISOString())} ago`}. `,
        ib({ type: "button", class: "link inline", onclick: discardDraft }, "trash", "Discard it"));
      return;
    }
    el.replaceChildren();
  },
});
function discardDraft() {
  draft.discard();
  const t = editing;
  const f = $("#todo-form");
  f.reset();
  if (t) { f.title.value = t.title; f.prompt.value = t.prompt; f.goal.checked = t.goal; f.priority.value = t.priority; }
  todoAttach.reset(t?.attachments || []);
  promptEditor.render();
  draft.open(draftKey(t));
  toast("Draft discarded");
}
$("#todo-clear").addEventListener("click", () => {
  const f = $("#todo-form");
  const project = f.project.value;
  draft.discard();
  f.reset();
  f.project.value = project;
  todoAttach.reset([]);
  promptEditor.render();
  draft.open(draftKey(null));
  f.title.focus();
  toast("Cleared");
});
// Clean up rewrites the instructions without the chatter around them (a pasted
// chat answer, say); Undo in the toast brings the original back.
$("#todo-refine").addEventListener("click", attempt(async () => {
  const f = $("#todo-form");
  const btn = $("#todo-refine");
  const before = f.prompt.value;
  if (!before.trim()) throw new Error("Write or paste instructions to clean up first.");
  const set = (v) => { f.prompt.value = v; promptEditor.render(); draft.changed(); };
  btn.disabled = true;
  f.prompt.readOnly = true;
  btn.lastChild.textContent = "Cleaning up…";
  try {
    const { prompt } = await api("POST", "/api/refine", { prompt: before });
    if (f.prompt.value !== before) return; // the form changed meanwhile
    set(prompt);
    toast("Instructions cleaned up", { tone: "ok", action: { label: "Undo", run: () => set(before) } });
  } finally {
    btn.disabled = false;
    f.prompt.readOnly = false;
    btn.lastChild.textContent = "Clean up";
  }
}));
$("#todo-form").addEventListener("input", () => draft.changed());
$("#todo-form").addEventListener("change", () => draft.changed());
const askAttach = attachBox($("#ask-attach"), $("#ask-input"));

// ------------------------------------------------------------------ state
const LANES = [
  { key: "draft", label: "Drafts", statuses: ["draft"], empty: "Drafts wait here until you queue them." },
  { key: "queued", label: "Queued", statuses: ["queued"], empty: "Nothing waiting. New tasks start here." },
  { key: "in_progress", label: "Running", statuses: ["in_progress"], empty: "No agents working right now." },
  { key: "review", label: "Review", statuses: ["review"], empty: "Nothing to review. Finished work lands here." },
  { key: "merging", label: "Merging", statuses: ["merging"], empty: "The merge queue is clear." },
  { key: "done", label: "Done", statuses: ["merged", "failed"], empty: "Merged and failed tasks show up here." },
];
const STATUS_LABEL = { draft: "Draft", queued: "Queued", in_progress: "Running", review: "Ready for review", merging: "Merging", merged: "Merged", failed: "Failed" };

const state = {
  projects: [],
  project: null,
  todos: new Map(),
  lastLine: new Map(),
  lane: null,          // mobile: selected lane key
  detail: null,        // open todo id
  pane: "diff",
  diff: "",
  diffOpen: new Set(), // diff files the user expanded in the open todo
  procs: [],
  perms: [],           // pending permission requests for this project
  usage: null,
  view: "board",
  query: "",           // board search (/)
  showOld: false,      // show merged todos older than a day
  unpushed: 0,         // commits on the default branch origin doesn't have
  unpushedTodos: null, // ids of merged todos origin doesn't have yet (null until known)
  comments: loadComments(), // todo id → [{file, line, side, code, text}] (diff review notes)
  collapsed: new Set((() => { try { return JSON.parse(localStorage.getItem("dash.collapsed") || "[]"); } catch { return []; } })()), // desktop: minimized lane keys
};
const DAY = 24 * 3600 * 1000;

function loadComments() {
  try { return JSON.parse(localStorage.getItem("dash.comments") || "{}"); } catch { return {}; }
}
function saveComments() {
  try { localStorage.setItem("dash.comments", JSON.stringify(state.comments)); } catch {}
}

// ------------------------------------------------------------------ navigation
function showView(name) {
  const apply = () => applyView(name);
  if (name !== state.view && document.startViewTransition && !reduceMotion.matches) {
    document.startViewTransition(apply);
    return;
  }
  apply();
}

function applyView(name) {
  state.view = name;
  try { localStorage.setItem("dash.view", name); } catch {}
  $$(".nav > button").forEach((b) => {
    const on = b.dataset.view === name;
    b.classList.toggle("active", on);
    b.toggleAttribute("aria-current", on);
    if (on) b.setAttribute("aria-current", "page");
  });
  $$(".view").forEach((v) => v.classList.toggle("active", v.id === `view-${name}`));
  if (name === "run") requestAnimationFrame(() => { fitTerm(); ensureShell(); });
  if (name === "history") loadGraph().catch(fail);
  if (name === "files" && state.project) loadFiles().catch(fail); // at startup the project (and the files code below) isn't ready yet
}
$$(".nav > button[data-view]").forEach((b) => b.addEventListener("click", () => showView(b.dataset.view)));
{
  const saved = (() => { try { return localStorage.getItem("dash.view"); } catch { return null; } })();
  if (saved && $(`.nav > button[data-view="${saved}"]`)) applyView(saved);
}

// ------------------------------------------------------------------ live events
// One live connection per computer, so notifications arrive from all of them.
const sockets = new Map(); // machine name → { ws, live }
async function connectAll() {
  state.machines = await api("GET", "/api/machines");
  for (const m of state.machines) if (m.ok && !sockets.has(m.name)) connectEvents(m);
  await loadProjects();
}

function connectEvents(m) {
  const ws = new WebSocket(wsURL(on(m.prefix, "/ws/events")));
  const sock = { ws, live: false };
  sockets.set(m.name, sock);
  ws.onopen = () => {
    sock.live = true;
    refreshLive();
    if (m.local) checkForUpdate(); // a reconnect often means Dash restarted, maybe updated
    loadProjects().catch(fail);
  };
  ws.onclose = async () => {
    sock.live = false;
    refreshLive();
    // Logged out: go to the login page. Server down or restarting: keep trying.
    const me = await fetch("/api/me").catch(() => null);
    if (me?.status === 401) { location.replace("/login.html"); return; }
    setTimeout(() => connectEvents(m), m.local ? 1500 : 5000);
  };
  ws.onmessage = (msg) => onEvent(JSON.parse(msg.data), m);
}

const multi = () => (state.machines || []).length > 1;
function refreshLive() { setLive(!!sockets.get(state.project?.machine || state.machines?.[0]?.name)?.live); }
function setLive(on) {
  $("#live").classList.toggle("on", on);
  $("#live").title = on ? "Live updates connected" : "Live updates disconnected — reconnecting";
  $("#live-label").textContent = on ? "Live" : "Offline";
}

function onEvent(ev, m = { name: "" }) {
  const sameMachine = !state.project || m.name === state.project.machine;
  const mine = state.project && ev.project_id === state.project.id && sameMachine;
  if (!mine) elsewhere(ev, m);
  switch (ev.type) {
    case "project.updated":
      loadProjects().catch(fail);
      break;
    case "todo.updated":
      if (!mine) break;
      {
        const prev = state.todos.get(ev.todo_id);
        state.todos.set(ev.todo_id, ev.data);
        renderBoard();
        if (state.detail === ev.todo_id) {
          renderDetail();
          if (prev?.status !== ev.data.status && ev.data.worktree) loadDiff();
        }
        if (prev && prev.status !== ev.data.status) {
          if (ev.data.status === "review") { toast(title(ev.data), { tone: "review", head: "Ready for review", action: openTodo(ev.todo_id) }); notify("Ready for review", ev.data); }
          if (ev.data.status === "failed") { toast(title(ev.data), { tone: "error", head: "Failed", action: openTodo(ev.todo_id) }); notify("Failed", ev.data, ev.data.error); }
          if (ev.data.status === "merged") { toast(title(ev.data), { tone: "ok", head: "Merged", icon: "merge" }); notify("Merged", ev.data); loadUnpushed().catch(fail); }
        }
        if (prev && prev.revert?.commit !== ev.data.revert?.commit) loadUnpushed().catch(fail);
        if (prev && !prev.revert && ev.data.revert) {
          const url = ev.data.revert.pr_url;
          toast(title(ev.data), { tone: "pr", icon: "undo", head: url ? "Revert pull request opened" : "Reverted", action: url ? { label: "View", run: () => window.open(url, "_blank", "noopener") } : openTodo(ev.todo_id) });
        }
        if (prev && !prev.pr && ev.data.pr) toast(title(ev.data), { tone: "pr", head: `Pull request #${ev.data.pr.number} opened`, action: { label: "View", run: () => window.open(ev.data.pr.url, "_blank", "noopener") } });
      }
      break;
    case "todo.deleted":
      if (!mine) break;
      state.todos.delete(ev.todo_id);
      if (state.detail === ev.todo_id) closeDetail();
      renderBoard();
      break;
    case "todo.output":
      state.lastLine.set(ev.todo_id, String(ev.data).split("\n").pop());
      if (mine) updateLiveLine(ev.todo_id);
      if (state.detail === ev.todo_id) {
        const log = $("#d-log");
        const stick = log.parentElement.scrollTop + log.parentElement.clientHeight >= log.parentElement.scrollHeight - 40;
        log.textContent += `${new Date(ev.time).toLocaleTimeString(timeLocale)} ${ev.data}\n`;
        if (stick && state.pane === "log") log.parentElement.scrollTop = log.parentElement.scrollHeight;
      }
      break;
    case "git.op":
      if (mine || (!ev.project_id && sameMachine)) addActivity(ev);
      if (mine) refreshGraph();
      break;
    case "merge.queue":
      if (sameMachine) $("#merge-status").textContent = ev.data.pending ? `${ev.data.pending} in merge queue` : "";
      break;
    case "process.updated":
      if (mine) loadProcs().catch(fail);
      break;
    case "permission.updated":
      if (!mine) break;
      state.perms = state.perms.filter((p) => p.id !== ev.data.id);
      if (!ev.data.decision) {
        state.perms.push(ev.data);
        const t = state.todos.get(ev.data.todo_id);
        toast(t ? `${describePerm(ev.data).title} · ${title(t)}` : describePerm(ev.data).title, { tone: "approval", head: "Claude needs your approval", action: t ? { label: "Review", run: () => openDetail(t.id) } : null });
        if (t) notify(`Claude wants to ${describePerm(ev.data).title}`, t, describePerm(ev.data).detail);
      }
      renderPerms();
      break;
    case "usage.updated":
      if (!sameMachine) break;
      state.usage = ev.data;
      renderUsage();
      break;
    case "ci.updated":
      if (!mine) break;
      if (state.ci?.state && state.ci.state !== "failing" && ev.data.state === "failing") {
        toast(ev.data.todo_id ? "Claude is on it" : "", { tone: "error", head: `Build failing on ${ev.data.branch}`, action: ev.data.todo_id ? openTodo(ev.data.todo_id) : null });
        notify(`Build failing on ${ev.data.branch}`, { title: state.project.name, prompt: "" });
      }
      if (state.ci?.state === "failing" && ev.data.state === "passing") toast("", { tone: "ok", head: `Build passing again on ${ev.data.branch}` });
      state.ci = ev.data;
      renderCI();
      break;
  }
}

// Things that happen in projects you're not looking at, possibly on another
// computer: tell the user about the ones that need them.
const seen = new Map(); // "machine/todo" → last status
function elsewhere(ev, m) {
  const p = (state.projects || []).find((x) => x.id === ev.project_id && x.machine === m.name);
  const where = p ? (multi() ? `${p.name} on ${m.name}` : p.name) : m.name;
  if (ev.type === "todo.updated") {
    const key = `${m.name}/${ev.todo_id}`;
    const prev = seen.get(key);
    seen.set(key, ev.data.status);
    if (!prev || prev === ev.data.status) return;
    const go = p ? { label: "Go", run: async () => { await selectProject(p); await openDetail(ev.todo_id); } } : null;
    if (ev.data.status === "review") { toast(`${title(ev.data)} · ${where}`, { tone: "review", head: "Ready for review", action: go }); notify("Ready for review", ev.data, where); }
    if (ev.data.status === "failed") notify("Failed", ev.data, `${where}: ${ev.data.error || ""}`);
  }
  if (ev.type === "permission.updated" && !ev.data.decision) {
    toast(`${describePerm(ev.data).title} · ${where}`, { tone: "approval", head: "Claude needs your approval", action: p ? { label: "Go", run: async () => { await selectProject(p); await openDetail(ev.data.todo_id); } } : null });
    notify(`Claude wants to ${describePerm(ev.data).title}`, { title: where, prompt: "" }, describePerm(ev.data).detail);
  }
}

const projectKey = (p) => (p ? `${p.machine}/${p.id}` : "");

// ------------------------------------------------------------------ projects
async function loadProjects() {
  if (!state.machines) state.machines = await api("GET", "/api/machines");
  const lists = await Promise.all(state.machines.map(async (m) => {
    if (!m.ok) return [];
    try {
      return (await api("GET", "/api/projects", null, m.prefix)).map((p) => ({ ...p, machine: m.name, prefix: m.prefix }));
    } catch (e) {
      m.ok = false;
      m.error = e.message;
      return [];
    }
  }));
  state.projects = lists.flat();
  const saved = (() => { try { return localStorage.getItem("dash.project"); } catch { return null; } })();
  const want = projectKey(state.project) || saved;
  const next = state.projects.find((p) => projectKey(p) === want || p.id === want) || state.projects[0] || null;
  if (projectKey(next) !== projectKey(state.project)) await selectProject(next);
  else { state.project = next; renderProjectHeader(); }
  renderProjectList();
}

async function selectProject(p) {
  state.project = p;
  state.todos = new Map();
  state.unpushed = 0;
  state.unpushedTodos = null;
  state.lane = null;
  closeDetail();
  try { if (p) localStorage.setItem("dash.project", projectKey(p)); } catch {}
  renderProjectHeader();
  refreshLive();
  loadUsage().catch(() => {});
  renderProjectList();
  state.ci = null;
  renderCI();
  renderChatPane();
  if (!p) { state.perms = []; renderBoard(); renderProcs(); renderPerms(); renderGraph(null); renderFileTree(); renderFile(); return; }
  await Promise.all([loadTodos(), loadProcs(), loadPerms(), loadCI(), state.view === "history" && loadGraph(), state.view === "files" && loadFiles()]);
}

async function loadPerms() {
  if (!state.project) return;
  state.perms = await api("GET", `/api/permissions?project=${state.project.id}`);
  renderPerms();
}

function renderProjectHeader() {
  const p = state.project;
  $("#project-name").replaceChildren(...(p ? [projectDot(p), p.name].filter(Boolean) : ["No project"]));
  // The project's own color marks the top bar (and the phone's browser chrome).
  const app = $(".app");
  if (p?.color) app.style.setProperty("--project", p.color);
  else app.style.removeProperty("--project");
  app.classList.toggle("has-project-color", !!p?.color);
  $('meta[name="theme-color"]').content = p?.color || "#101722";
  // With several computers the header names the computer (the branch fits on wide screens too).
  $("#project-branch").textContent = !p ? "" : !multi() ? p.default_branch : desktop.matches ? `${p.default_branch} · ${p.machine}` : p.machine;
  $("#project-menu").hidden = !p;
  $("#pm-github").hidden = !p || !!p.remote_url;
  renderPushMain();
  renderQuick();
  const warn = $("#sync-warn");
  warn.hidden = !p?.sync_error;
  if (p?.sync_error) {
    warn.replaceChildren(h("strong", {}, `Can't sync ${p.default_branch} with GitHub`), h("span", {}, p.sync_error),
      h("span", { class: "hint" }, `Fix it in ${p.path}; Dash retries on the next merge.`));
  }
}

function renderProjectList() {
  renderSideProjects();
  renderChatPane();
  setLabel($("#notify-toggle"), notifyOn() ? "bell-off" : "bell", notifyLabel());
}

const notifyLabel = () => notifyOn() ? "Turn off notifications" : "Turn on notifications";

function openNewProject() {
  const f = $("#new-project");
  f.machine.closest(".field").hidden = !multi();
  f.machine.replaceChildren(...(state.machines || []).filter((m) => m.ok).map((m) => h("option", { value: m.name, selected: m.name === state.project?.machine }, m.local ? `${m.name} (this computer)` : m.name)));
  $("#new-project-sheet").showModal();
}

// A project's image icon, or its initial on its color.
const projectIcon = (p, el = h("span", { class: "side-project-icon", "aria-hidden": "true" })) => {
  el.style.setProperty("--project", p.color || "");
  el.replaceChildren(p.icon ? h("img", { src: on(p.prefix || "", `/api/uploads/${p.icon}`), alt: "" }) : [...p.name][0]?.toUpperCase() || "?");
  return el;
};
const projectDot = (p) => (p.color ? h("span", { class: "project-dot", style: `--project: ${p.color}`, "aria-hidden": "true" }) : null);

// Desktop sidebar / phone menu: every project, one click away. The current one
// shows its branch; its settings and actions live in the top bar's project menu.
function renderSideProjects() {
  const item = (p) => {
    const cur = projectKey(state.project) === projectKey(p);
    return h("li", { class: cur ? "current" : "" },
      h("button", {
        type: "button", class: "side-project", title: `${p.name}\n${p.path}`, "aria-current": cur ? "true" : "false",
        onclick: attempt(async () => { await selectProject(p); setMenu(false); }),
      },
      projectIcon(p),
      h("span", { class: "side-project-name" }, p.name),
      cur && p.default_branch ? h("span", { class: "side-project-branch" }, p.default_branch) : null));
  };
  const items = !multi() ? state.projects.map(item) : state.machines.flatMap((m) => [
    h("li", { class: "side-machine", title: m.ok ? "" : m.error || "unreachable" },
      h("span", { class: `machine-dot ${m.ok ? "ok" : "down"}`, "aria-hidden": "true" }), m.name),
    ...state.projects.filter((p) => p.machine === m.name).map(item),
  ]);
  $("#side-project-list").replaceChildren(...(items.length ? items : [h("li", { class: "machine-empty" }, "No projects yet")]));
}

async function cleanup() {
  const p = state.project;
  if (!p) throw new Error("Select a project first (p).");
  toast("Cleaning up…");
  const res = await api("POST", `/api/projects/${p.id}/cleanup`);
  toast(res.summary.charAt(0).toUpperCase() + res.summary.slice(1));
}

async function createGitHubRepo() {
  const p = state.project;
  const name = await ask({ title: "Create GitHub repository", body: "Creates a private repository with gh and pushes the default branch.", input: true, placeholder: p.name, ok: "Create" });
  if (name === null) return;
  await api("POST", `/api/projects/${p.id}/github`, { name: name || p.name, private: true });
  await loadProjects();
  toast("GitHub repository created");
}

// Phones open the sidebar's projects, actions and status as a drawer from the
// top bar; on desktop the same button collapses the sidebar to its icons.
const menuOpen = () => $(".app").classList.contains("menu-open");
const sideCollapsed = () => $(".app").classList.contains("side-collapsed");
function syncMenuBtn() {
  const btn = $("#menu-open");
  const label = !desktop.matches ? "Menu" : sideCollapsed() ? "Expand sidebar" : "Collapse sidebar";
  btn.setAttribute("aria-expanded", String(desktop.matches ? !sideCollapsed() : menuOpen()));
  btn.setAttribute("aria-label", label);
  btn.title = desktop.matches ? `${label} ([)` : "";
}
function setSideCollapsed(on) {
  $(".app").classList.toggle("side-collapsed", on);
  try { localStorage.setItem("dash.sideCollapsed", on ? "1" : "0"); } catch {}
  syncMenuBtn();
}
function setMenu(open) {
  open = open && !desktop.matches;
  $(".app").classList.toggle("menu-open", open);
  $("#menu-scrim").hidden = !open;
  $("#project-switch").setAttribute("aria-expanded", String(open));
  syncMenuBtn();
}
try { $(".app").classList.toggle("side-collapsed", localStorage.getItem("dash.sideCollapsed") === "1"); } catch {}
syncMenuBtn();
function openProjects() {
  if (desktop.matches && sideCollapsed()) return setPicker(true);
  renderProjectList();
  setMenu(true);
  ($(".side-project[aria-current=true]") || $(".side-project"))?.focus();
}
// Desktop: the top bar's project name opens a dropdown of every project.
// Phones use the drawer instead.
function setPicker(open) {
  const list = $("#project-picker");
  list.hidden = !open;
  $("#project-switch").setAttribute("aria-expanded", String(open));
  if (!open) return;
  const item = (p) => {
    const cur = projectKey(state.project) === projectKey(p);
    return h("button", {
      type: "button", role: "menuitem", title: p.path, "aria-current": cur ? "true" : "false",
      onclick: attempt(async () => { setPicker(false); if (!cur) await selectProject(p); }),
    }, h("span", { class: "project-name" }, projectDot(p), p.name), h("span", { class: "project-branch" }, p.default_branch));
  };
  const items = !multi() ? state.projects.map(item) : state.machines.flatMap((m) => {
    const ps = state.projects.filter((p) => p.machine === m.name);
    return [h("div", { class: "side-machine", title: m.ok ? "" : m.error || "unreachable" },
      h("span", { class: `machine-dot ${m.ok ? "ok" : "down"}`, "aria-hidden": "true" }), m.name), ...ps.map(item)];
  });
  list.replaceChildren(...(state.projects.length ? items : [h("div", { class: "machine-empty" }, "No projects yet")]),
    h("button", { type: "button", role: "menuitem", class: "picker-new", onclick: () => { setPicker(false); openNewProject(); } }, "+ New project"));
  ($("button[aria-current=true]", list) || $("button", list))?.focus();
}
$("#project-switch").addEventListener("click", (e) => {
  if (!desktop.matches) return openProjects();
  e.stopPropagation();
  setPicker($("#project-picker").hidden);
});
document.addEventListener("click", (e) => { if (!$("#project-picker").hidden && !e.target.closest(".project-picker")) setPicker(false); });
$("#project-picker").addEventListener("keydown", (e) => {
  const btns = $$("#project-picker button");
  const i = btns.indexOf(document.activeElement);
  const step = { ArrowDown: 1, j: 1, ArrowUp: -1, k: -1 }[e.key];
  if (step) btns[(i + step + btns.length) % btns.length].focus();
  else if (e.key === "Escape" || e.key === "q") { setPicker(false); $("#project-switch").focus(); }
  else return;
  e.preventDefault(); e.stopPropagation();
});
$("#menu-open").addEventListener("click", () => desktop.matches ? setSideCollapsed(!sideCollapsed()) : openProjects());
$("#menu-close").addEventListener("click", () => { setMenu(false); $("#menu-open").focus(); });
$("#menu-scrim").addEventListener("click", () => setMenu(false));
desktop.addEventListener("change", () => { setMenu(false); $("#project-picker").hidden = true; });
$("#side-new-project").addEventListener("click", openNewProject);
$("#notify-toggle").addEventListener("click", attempt(toggleNotifications));
$("#pm-settings").addEventListener("click", openSettings);
$("#pm-github").addEventListener("click", attempt(createGitHubRepo));
$("#push-main").addEventListener("click", attempt(pushDone));
$("#pm-cleanup").addEventListener("click", attempt(cleanup));
for (const menu of $$(".foot-menu")) {
  menu.querySelector(".foot-menu-list").addEventListener("click", () => { menu.open = false; });
  document.addEventListener("click", (e) => { if (!menu.contains(e.target)) menu.open = false; });
  menu.addEventListener("keydown", (e) => {
    if (e.key !== "Escape" || !menu.open) return;
    e.stopPropagation(); menu.open = false; menu.querySelector("summary").focus();
  });
}
$("#new-project").addEventListener("submit", attempt(async (e) => {
  if (e.submitter?.value === "cancel") return;
  e.preventDefault();
  const { machine, ...body } = Object.fromEntries(new FormData(e.target));
  const m = state.machines?.find((x) => x.name === machine) || state.machines?.[0] || { name: "", prefix: "" };
  const p = await api("POST", "/api/projects", body, m.prefix);
  e.target.reset();
  await loadProjects();
  await selectProject(state.projects.find((x) => x.id === p.id && x.machine === m.name));
  $("#new-project-sheet").close();
  toast(`Created ${p.name}`);
}));

// ------------------------------------------------------------------ board
async function loadTodos() {
  if (!state.project) return;
  const list = await api("GET", `/api/projects/${state.project.id}/todos`);
  state.todos = new Map(list.map((t) => [t.id, t]));
  renderBoard();
  if (state.detail) renderDetail();
  loadUnpushed().catch(fail);
}

async function loadUnpushed() {
  const p = state.project;
  if (!p?.remote_url || p.merge_mode === "pr") { state.unpushed = 0; renderPushMain(); return; }
  const { count, todos = [] } = await api("GET", `/api/projects/${p.id}/unpushed`);
  const same = (a, b) => a && a.size === b.length && b.every((id) => a.has(id));
  if (state.project !== p || (count === state.unpushed && same(state.unpushedTodos, todos))) return;
  state.unpushed = count;
  state.unpushedTodos = new Set(todos);
  renderBoard();
  renderPushMain();
}

async function pushDone() {
  const p = state.project;
  const btn = $("#push-main");
  btn.disabled = true;
  try {
    await api("POST", `/api/projects/${p.id}/push`);
    toast(`Pushed ${p.default_branch}`);
    await loadUnpushed();
  } finally { renderPushMain(); }
}

// The top bar's push button: shown for projects that push to GitHub directly.
function renderPushMain() {
  const p = state.project, n = state.unpushed;
  const btn = $("#push-main");
  btn.hidden = !p?.remote_url || p.merge_mode === "pr";
  if (btn.hidden) return;
  const label = n ? `Push ${n} ${n === 1 ? "commit" : "commits"} to ${p.default_branch}` : `${p.default_branch} is up to date with GitHub`;
  btn.disabled = !n;
  btn.title = label;
  btn.setAttribute("aria-label", label);
  $("#push-count").hidden = !n;
  $("#push-count").textContent = n > 99 ? "99+" : String(n);
}

function pushBar() {
  const n = state.unpushed;
  if (!n) return null;
  return ib({ type: "button", class: "btn primary push-done", onclick: attempt(pushDone) }, "push",
    `Push ${n} ${n === 1 ? "commit" : "commits"} to ${state.project.default_branch}`);
}

const title = (t) => t.title || t.prompt.split("\n")[0];
const byPriority = (a, b) => a.priority - b.priority || a.created_at.localeCompare(b.created_at);

const matches = (t, q) => !q || `${t.title} ${t.prompt}`.toLowerCase().includes(q.toLowerCase());
const isOld = (t) => t.status === "merged" && Date.now() - new Date(t.finished_at || t.updated_at) > DAY;

function laneItems() {
  const out = Object.fromEntries(LANES.map((l) => [l.key, []]));
  for (const t of state.todos.values()) {
    if (!matches(t, state.query)) continue;
    if (!state.showOld && isOld(t)) continue;
    const lane = LANES.find((l) => l.statuses.includes(t.status));
    if (lane) out[lane.key].push(t);
  }
  for (const k in out) {
    out[k].sort(k === "done" ? (a, b) => b.updated_at.localeCompare(a.updated_at) : byPriority);
  }
  return out;
}

function renderBoard() {
  if (drag.active) return; // don't rebuild under the user's finger; we re-render on drop
  const before = flipFirst();
  renderBoardNow();
  flipPlay(before);
}

// FLIP: cards glide from where they were to where they are now, so a live
// status change reads as movement instead of a jump. New cards fade in.
function flipFirst() {
  const m = new Map();
  for (const el of $$(".todo[data-id]")) m.set(el.dataset.id, el.getBoundingClientRect());
  return m;
}
let boardRendered = false;
function flipPlay(before) {
  const first = !boardRendered;
  boardRendered = true;
  if (reduceMotion.matches || first) return;
  for (const el of $$(".todo[data-id]")) {
    const was = before.get(el.dataset.id);
    const now = el.getBoundingClientRect();
    if (!now.width) continue; // in a hidden lane (mobile)
    if (!was || !was.width) {
      el.animate([{ opacity: 0, transform: "scale(.97)" }, { opacity: 1, transform: "none" }], { duration: 240, easing: EASE });
      continue;
    }
    const dx = was.left - now.left, dy = was.top - now.top;
    if (Math.abs(dx) + Math.abs(dy) < 1) continue;
    el.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: "none" }], { duration: 320, easing: EASE });
  }
}

function renderBoardNow() {
  const items = laneItems();
  const empty = $("#board-empty");
  if (!state.project) {
    $("#board").replaceChildren();
    $("#lane-tabs").replaceChildren();
    $("#lane-chips").replaceChildren();
    empty.hidden = false;
    empty.replaceChildren(
      // Optional illustration: save as web/static/img/empty-board.webp, 960x720 (4:3). Hidden if missing.
      // Convert: magick in.png -resize 960x720^ -gravity center -extent 960x720 -quality 85 web/static/img/empty-board.webp
      // Files are embedded in the binary: rebuild and restart dash afterwards.
      art("img/empty-board.webp", 480, 360),
      h("p", { class: "empty-title" }, "Create your first project"),
      h("p", {}, "A project is a git repository. Every task runs in its own worktree, so several can run at once."),
      ib({ class: "btn primary", onclick: openNewProject }, "plus", "New project"));
    $("#new-todo").hidden = true;
    return;
  }
  empty.hidden = true;
  $("#new-todo").hidden = false;

  // Mobile opens on whatever needs attention first.
  if (!state.lane || laneHidden(state.lane)) {
    state.lane = ["review", "in_progress", "queued", "draft"].find((k) => items[k].length) || "queued";
  }

  $("#lane-tabs").replaceChildren(...LANES.map((l) => h("button", {
    role: "tab", class: `lane-tab s-${l.key === "done" ? "merged" : l.key}`, "data-lane": l.key, hidden: laneHidden(l.key),
    "aria-selected": String(state.lane === l.key), "data-count": items[l.key].length,
    onclick: () => { state.lane = l.key; renderBoard(); },
  }, l.label, h("span", { class: "n" }, items[l.key].length))));

  // Desktop: minimized columns leave the board and show as chips in the top bar.
  $("#lane-chips").replaceChildren(...LANES.filter((l) => state.collapsed.has(l.key) && !laneHidden(l.key)).map((l) => h("button", {
    type: "button", class: `lane-tab lane-chip s-${l.key === "done" ? "merged" : l.key}`, "data-lane": l.key,
    "data-count": items[l.key].length, title: `Expand ${l.label}`, onclick: () => toggleCollapsed(l.key),
  }, l.label, h("span", { class: "n" }, items[l.key].length))));

  $("#board").replaceChildren(...LANES.map((l, li) => h("section", {
    "data-lane": l.key, hidden: laneHidden(l.key),
    class: `col s-${l.key === "done" ? "merged" : l.key}${state.lane === l.key ? " active" : ""}${keys.active && keys.cur.lane === li ? " cursor" : ""}${state.collapsed.has(l.key) ? " collapsed" : ""}`, "aria-label": l.label,
  },
    h("header", { class: "col-head" },
      h("span", { class: "col-label" }, l.label), h("span", { class: "n" }, items[l.key].length),
      ib({ class: "icon-btn col-toggle", title: `Minimize ${l.label}`, onclick: () => toggleCollapsed(l.key) }, "minimize")),
    h("div", { class: "col-body" },
      l.key === "done" ? pushBar() : null,
      items[l.key].length
        ? h("ol", { class: "rail" }, items[l.key].map((t, ri) => h("li", {}, todoRow(t, li, ri))))
        : h("p", { class: "col-empty" }, state.query ? "No matches." : l.empty),
      l.key === "done" ? oldToggle() : null,
      l.key === "done" ? clearDoneBtn() : null))));
  syncSearchBar();
  updateNeedsYou(items);

  $(".lane-tab[aria-selected=true]")?.scrollIntoView({ block: "nearest", inline: "nearest" });

  const review = items.review.length + state.perms.length;
  const badge = $("#review-badge");
  if (String(review) !== badge.textContent && review && !reduceMotion.matches) {
    badge.animate([{ transform: "scale(1.35)" }, { transform: "scale(1)" }], { duration: 260, easing: EASE });
  }
  badge.hidden = !review;
  badge.textContent = review;
}

function toggleCollapsed(key) {
  if (!state.collapsed.delete(key)) state.collapsed.add(key);
  try { localStorage.setItem("dash.collapsed", JSON.stringify([...state.collapsed])); } catch {}
  renderBoard();
}

function oldToggle() {
  const hidden = [...state.todos.values()].filter((t) => isOld(t) && matches(t, state.query)).length;
  if (!hidden && !state.showOld) return null;
  return ib({ class: "link older", onclick: () => { state.showOld = !state.showOld; renderBoard(); } }, state.showOld ? "up" : "down",
    state.showOld ? "Hide merged tasks older than a day" : `Show ${hidden} older merged ${hidden === 1 ? "task" : "tasks"}`);
}

const doneTodos = () => [...state.todos.values()].filter((t) => t.status === "merged" || t.status === "failed");

function clearDoneBtn() {
  if (!doneTodos().length) return null;
  return ib({ class: "link older", onclick: attempt(clearDone) }, "trash", "Clear Done");
}

async function clearDone() {
  const list = doneTodos();
  if (!list.length) return;
  const failed = list.filter((t) => t.status === "failed").length;
  const unpushed = list.filter((t) => t.status === "merged" && state.unpushedTodos?.has(t.id)).length;
  const n = list.length;
  if (!await ask({ title: unpushed ? `Not all done tasks are pushed — clear ${n} anyway?` : `Clear ${n} done ${n === 1 ? "task" : "tasks"}?`,
    body: `Deletes every merged and failed task in this project${failed ? `, including the worktrees and branches of ${failed} failed` : ""}. This can't be undone.` +
      (unpushed ? ` ${unpushed} merged ${unpushed === 1 ? "task hasn't" : "tasks haven't"} been pushed yet. Their changes are not discarded: the commits stay on the local default branch and can still be pushed.` : ""),
    ok: "Clear", danger: true })) return;
  const res = await Promise.allSettled(list.map((t) => api("DELETE", `/api/todos/${t.id}`)));
  if (list.some((t) => t.id === state.detail)) closeDetail();
  const bad = res.filter((r) => r.status === "rejected").length;
  toast(bad ? `Cleared ${n - bad}, ${bad} failed` : `Cleared ${n} ${n === 1 ? "task" : "tasks"}`);
}

// "2m", "3h", "4d"
function ago(iso) {
  const s = Math.max(0, (Date.now() - new Date(iso)) / 1000);
  if (s < 60) return "now";
  if (s < 3600) return `${Math.floor(s / 60)}m`;
  if (s < DAY / 1000) return `${Math.floor(s / 3600)}h`;
  return `${Math.floor(s / 86400)}d`;
}

// A merged todo is pushed once origin has its commit (in "pr" mode, merging is pushing).
function isPushed(t) {
  const p = state.project;
  if (t.status !== "merged" || !p?.remote_url) return false;
  if (p.merge_mode === "pr") return true;
  return !!state.unpushedTodos && !state.unpushedTodos.has(t.id);
}

function todoRow(t, li = -1, ri = -1) {
  const atCursor = keys.active && keys.cur.lane === li && keys.cur.row === ri;
  let sub = t.prompt.replace(/\s+/g, " ");
  let subClass = "todo-sub";
  if (t.summary && t.status === "merged") sub = t.summary;
  const fixing = t.sent_back && ["queued", "in_progress"].includes(t.status) ? t.sent_back : "";
  if (fixing && t.status === "queued") sub = `Sent back from merge: ${fixing}`;
  if (t.status === "in_progress") { sub = state.lastLine.get(t.id) || "Working…"; subClass += " progress"; }
  if (t.paused) sub = t.status === "in_progress" ? "Pausing…" : "Paused";
  if (t.error) { sub = t.error; subClass += " err"; }
  if (t.reviewing) { sub = "Claude is reviewing…"; subClass = "todo-sub progress"; }
  if (state.perms.some((p) => p.todo_id === t.id)) { sub = "Waiting for your approval"; subClass = "todo-sub waiting"; }
  const checkTag = t.checks && ["review", "merging", "failed"].includes(t.status)
    ? h("span", { class: `check-tag ${t.checks.passed ? "pass" : "fail"}` }, t.checks.passed ? "Tests pass" : "Tests fail")
    : null;
  return h("button", {
    class: `todo s-${t.status}${isPushed(t) ? " pushed" : ""}${t.goal ? " goal" : ""}${t.reviewing ? " reviewing" : ""}${state.detail === t.id ? " selected" : ""}${atCursor ? " cursor" : ""}`,
    "data-id": t.id, onclick: () => openDetail(t.id),
  },
    h("span", { class: "node", "aria-hidden": "true" }),
    h("span", { class: "todo-main" }, h("span", { class: "todo-title" }, title(t)), h("span", { class: subClass }, sub)),
    h("span", { class: "todo-side" },
      checkTag,
      t.paused ? h("span", { class: "paused-tag" }, "Paused") : null,
      t.reviewing ? h("span", { class: "reviewing-tag" }, "Reviewing") : null,
      t.goal ? h("span", { class: "goal-tag" }, "Milestone") : null,
      t.pr && t.status !== "merged" ? h("span", { class: "pr-tag" }, `PR #${t.pr.number}`) : null,
      t.revert ? h("span", { class: "revert-tag" }, "Reverted") : null,
      t.ci_run ? h("span", { class: "ci-tag" }, "Build fix") : null,
      fixing ? h("span", { class: "sentback-tag", title: `Sent back from merge: ${fixing}` }, /conflict/.test(fixing) ? "Merge conflict" : "Failing checks") : null,
      t.attachments?.length ? h("span", { class: "attach-tag", title: `${t.attachments.length} attached` }, clip(), String(t.attachments.length)) : null,
      t.diff_files && ["review", "merging", "merged", "failed"].includes(t.status)
        ? h("span", { class: "diffsize", title: `${t.diff_files} ${t.diff_files === 1 ? "file" : "files"} changed` },
          h("span", { class: "plus" }, `+${t.diff_add || 0}`), " ", h("span", { class: "minus" }, `−${t.diff_del || 0}`))
        : null,
      t.status === "in_progress" && t.started_at ? h("span", { title: "Running for" }, ago(t.started_at)) : null,
      t.status === "review" && t.finished_at ? h("span", { title: "Waiting for review" }, ago(t.finished_at)) : null,
      t.priority ? h("span", {}, `P${t.priority}`) : null,
      t.status === "review" && !t.reviewing ? h("span", { class: "card-actions" }, reviewChip(t), approveChip(t)) : null,
      t.status === "draft" ? h("span", { class: "card-actions" }, enqueueChip(t)) : null));
}

// Spans, not buttons: the card itself is a <button>, which can't nest one.
function reviewChip(t) {
  return h("span", {
    class: "review-chip", role: "button", title: "Have Claude review the changes",
    onpointerdown: (e) => e.stopPropagation(),
    onclick: (e) => {
      e.stopPropagation();
      attempt(async () => { await openDetail(t.id); reviewTodo(); })();
    },
  }, ico("eye"), "Review");
}

function approveChip(t) {
  return h("span", {
    class: "approve-chip", role: "button", title: "Approve and merge without opening the diff",
    onpointerdown: (e) => e.stopPropagation(),
    onclick: (e) => {
      e.stopPropagation();
      attempt(async () => { await api("POST", `/api/todos/${t.id}/approve`); toast("Approved — merging"); })();
    },
  }, ico("check"), "Approve");
}

function enqueueChip(t) {
  return h("span", {
    class: "enqueue-chip", role: "button", title: "Move to the queue",
    onpointerdown: (e) => e.stopPropagation(),
    onclick: (e) => {
      e.stopPropagation();
      attempt(todoKey)(t, "s");
    },
  }, ico("queue"), "Enqueue");
}

function updateLiveLine(id) {
  const el = $(`.todo[data-id="${id}"] .todo-sub.progress`);
  if (el) el.textContent = state.lastLine.get(id);
}

// ------------------------------------------------------------------ new / edit todo
let editing = null;
let pickProject = false;
// pick lets you choose the project, for todos made outside a project (the global chat).
function openTodoForm(t = null, { pick = false } = {}) {
  editing = t;
  pickProject = pick && !t;
  const f = $("#todo-form");
  f.reset();
  $("#todo-project-field").hidden = !pickProject;
  if (pickProject) {
    f.project.replaceChildren(...state.projects.map((p) =>
      h("option", { value: projectKey(p) }, multi() ? `${p.name} · ${p.machine}` : p.name)));
    f.project.value = projectKey(state.project);
  }
  $("#todo-sheet-title").textContent = t ? "Edit task" : "New task";
  $("#todo-clear").hidden = !!t;
  if (t) {
    f.title.value = t.title;
    f.prompt.value = t.prompt;
    f.goal.checked = t.goal;
    f.priority.value = t.priority;
  }
  todoAttach.reset(t?.attachments || []);
  promptEditor.render();
  draft.open(draftKey(t));
  $("#todo-sheet").returnValue = ""; // Esc keeps the previous close's value
  $("#todo-sheet").showModal();
  (t ? f.prompt : f.title).focus();
}
$("#new-todo").addEventListener("click", () => openTodoForm());
$("#todo-sheet").addEventListener("close", attempt(async () => {
  const action = $("#todo-sheet").returnValue;
  if (action !== "draft" && action !== "queue") {
    const kept = draft.has(draftKey(editing));
    draft.close();
    if (draft.has(draftKey(editing)) && !kept) toast("Your draft is kept; open the form again to continue");
    return;
  }
  draft.flush(); // if saving fails below, the draft is still there
  const f = $("#todo-form");
  await todoAttach.settled();
  const body = { title: f.title.value.trim(), prompt: f.prompt.value.trim(), goal: f.goal.checked, priority: Number(f.priority.value) || 0, attachments: todoAttach.ids() };
  if (!body.title && !body.prompt) throw new Error("Add a title or instructions before saving.");
  if (editing) {
    await api("PATCH", `/api/todos/${editing.id}`, body);
    if (action === "queue" && editing.status !== "queued") await api("POST", `/api/todos/${editing.id}/enqueue`);
    toast(action === "queue" ? "Saved and queued" : "Saved");
  } else {
    const p = (pickProject && state.projects.find((x) => projectKey(x) === f.project.value)) || state.project;
    // Attachments are uploaded to the current project's computer.
    if (body.attachments.length && p.prefix !== here()) throw new Error(`Attachments can't be sent to ${p.name} on ${p.machine}; remove them or pick a project on this computer.`);
    await api("POST", `/api/projects/${p.id}/todos`, { ...body, enqueue: action === "queue" }, p.prefix || "");
    const other = projectKey(p) !== projectKey(state.project);
    toast(`${action === "queue" ? "Added to queue" : "Saved as draft"}${other ? ` in ${p.name}` : ""}`);
    if (!other) state.lane = action === "queue" ? "queued" : "draft";
  }
  draft.done();
}));
// Native form validation would block "Save as draft" too; we validate on close instead.
$("#todo-form").noValidate = true;

// ------------------------------------------------------------------ detail
async function openDetail(id) {
  state.detail = id;
  const t = state.todos.get(id);
  state.pane = t?.worktree ? "diff" : t?.status === "draft" ? "chat" : "log";
  state.diff = "";
  state.diffOpen = new Set();
  $("#detail").hidden = false;
  $("#scrim").hidden = !desktop.matches;
  renderDetail();
  if (state.pane === "chat") todoChat.input.focus();
  $$(".todo.selected").forEach((e) => e.classList.remove("selected"));
  $(`.todo[data-id="${id}"]`)?.classList.add("selected");
  $("#d-log").textContent = "";
  await Promise.all([loadLog(), loadDiff(), loadTodoChat()]).catch(fail);
}

function closeDetail() {
  const wasOpen = state.detail && !$("#detail").hidden;
  state.detail = null;
  const hide = () => { if (!state.detail) { $("#detail").hidden = true; $("#scrim").hidden = true; } };
  if (wasOpen) leave($("#detail"), "closing", hide); else hide();
  $$(".todo.selected").forEach((e) => e.classList.remove("selected"));
}
$("#d-close").addEventListener("click", closeDetail);
$("#scrim").addEventListener("click", closeDetail);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && state.detail && !document.querySelector("dialog[open]")) closeDetail();
});

async function loadLog() {
  const id = state.detail;
  const text = await api("GET", `/api/todos/${id}/log`);
  if (state.detail === id) $("#d-log").textContent = text || "No output yet.";
}
async function loadDiff() {
  const id = state.detail;
  const t = state.todos.get(id);
  if (!t?.worktree) { state.diff = ""; renderPane(); return; }
  const text = await api("GET", `/api/todos/${id}/diff`).catch((e) => `error: ${e.message}`);
  if (state.detail !== id) return;
  state.diff = text;
  renderPane();
}

function renderDetail() {
  const t = state.todos.get(state.detail);
  if (!t) return;
  $("#d-title").textContent = title(t);
  $("#d-meta").replaceChildren(...[
    h("span", { class: `status s-${t.status}` }, STATUS_LABEL[t.status] || t.status),
    t.goal ? h("span", { class: "goal-tag" }, "Milestone") : null,
    t.worktree ? h("span", { class: "branch" }, t.worktree.branch) : null,
    t.priority ? h("span", {}, `Priority ${t.priority}`) : null,
    t.runs ? h("span", {}, `${t.runs} ${t.runs === 1 ? "run" : "runs"}${t.cost_usd ? ` · ≈$${t.cost_usd.toFixed(2)}` : ""}`) : null,
    t.auto_fixes ? h("span", {}, `Fixed automatically ${t.auto_fixes}×`) : null,
    t.pr ? h("a", { class: "pr-link", href: t.pr.url, target: "_blank", rel: "noopener" }, `Pull request #${t.pr.number}${t.pr.state === "OPEN" ? "" : ` · ${t.pr.state.toLowerCase()}`}`) : null,
    t.merged_commit ? h("span", { class: "branch", title: t.merged_commit }, t.merged_commit.slice(0, 8)) : null,
    t.revert ? (t.revert.pr_url
      ? h("a", { class: "revert-tag", href: t.revert.pr_url, target: "_blank", rel: "noopener" }, "Revert pull request")
      : h("span", { class: "revert-tag", title: t.revert.commit }, "Reverted")) : null,
  ].filter(Boolean));
  const gallery = $("#d-attach");
  gallery.hidden = !t.attachments?.length;
  gallery.replaceChildren(...(t.attachments || []).map((a) => attachThumb(a)));
  renderChecks(t);
  renderPerms();
  $("#d-prompt").replaceChildren(
    ib({ type: "button", class: "btn small copy-prompt", onclick: attempt(() => copy(t.prompt, "Prompt copied")) }, "copy", "Copy"),
    t.prompt,
    ...(t.feedback?.length ? [h("ol", { class: "feedback-list" }, t.feedback.map((f) => h("li", {}, f)))] : []));
  $("#d-prompt-wrap").open = !t.worktree;
  $("#d-error").hidden = !t.error;
  $("#d-error").textContent = t.error || "";
  renderActions(t);
  renderPane();
}

function renderActions(t) {
  const post = (verb, body, msg) => attempt(async () => { await api("POST", `/api/todos/${t.id}/${verb}`, body); toast(msg); });
  const b = (icon, label, onclick, cls = "") => ib({ class: `btn ${cls}`, onclick }, icon, label);
  const rework = attempt(() => reworkTodo(t));
  const btns = [];
  switch (t.status) {
    case "draft":
      btns.push(b("edit", "Edit", () => openTodoForm(t)), b("queue", "Add to queue", post("enqueue", null, "Added to queue"), "primary grow"));
      break;
    case "queued":
      btns.push(b("edit", "Edit", () => openTodoForm(t)), b("inbox", "Move to drafts", post("cancel", null, "Moved to drafts"), "grow"));
      if (t.paused) btns.push(b("play", "Resume", post("resume", null, "Resumed"), "primary grow"));
      break;
    case "in_progress":
      if (!t.paused) btns.push(b("pause", "Pause", post("pause", null, "Pausing")));
      btns.push(b("stop", "Stop", post("cancel", null, "Stopping"), "danger grow"));
      break;
    case "review":
      if (t.reviewing) {
        btns.push(h("span", { class: "btn grow reviewing" }, ico("eye"), "Claude is reviewing…"));
        break;
      }
      if (commentsFor(t.id).length) {
        btns.push(b("send", `Send ${commentsFor(t.id).length} ${commentsFor(t.id).length === 1 ? "comment" : "comments"}`, attempt(() => sendComments(t)), "primary"));
      } else {
        btns.push(b("redo", "Rework", rework));
      }
      btns.push(b("eye", "Review", reviewTodo));
      btns.push(b("merge", "Approve and merge", post("approve", null, "Approved — merging"), "review grow"));
      break;
    case "merging":
      if (t.pr) btns.push(h("a", { class: "btn primary grow", href: t.pr.url, target: "_blank", rel: "noopener" }, ico("external"), `Open pull request #${t.pr.number}`));
      break;
    case "failed":
      btns.push(t.worktree ? b("redo", "Rework", rework) : b("edit", "Edit", () => openTodoForm(t)));
      btns.push(t.worktree && t.error?.startsWith("merge:")
        ? b("merge", "Retry merge", post("approve", null, "Merging again"), "review grow")
        : b("redo", "Retry", post("enqueue", null, "Queued again"), "primary grow"));
      break;
    case "merged":
      if (!t.revert) btns.push(b("undo", "Revert", attempt(() => revertTodo(t)), "grow"));
      break;
  }
  $("#d-actions").replaceChildren(...btns);
}

$("#d-more").addEventListener("click", attempt(async () => {
  const t = state.todos.get(state.detail);
  if (!t) return;
  const choices = [];
  if (t.worktree && ["review", "failed"].includes(t.status)) {
    const serve = techFor("web:run"), label = serve.label || "Start server";
    choices.push([serve.icon || "play", `Try it: ${label[0].toLowerCase()}${label.slice(1)} in this worktree`, () => startProc({ kind: "web", preset: "run", todo_id: t.id })]);
    choices.push(["terminal", "Open shell in this worktree", () => startProc({ kind: "pty", todo_id: t.id })]);
  }
  if (t.pr) choices.push(["external", `Open pull request #${t.pr.number}`, () => window.open(t.pr.url, "_blank", "noopener")]);
  if (t.status === "merged" && !t.revert) choices.push(["undo", "Revert this change", () => revertTodo(t)]);
  if (!["in_progress", "merging"].includes(t.status)) {
    choices.push(["flag", t.goal ? "Unmark milestone" : "Mark as milestone", () => api("PATCH", `/api/todos/${t.id}`, { goal: !t.goal })]);
    if (t.worktree && state.project?.test_command) choices.push(["check", "Run the tests again", () => api("POST", `/api/todos/${t.id}/test`).then(() => toast("Running tests…"))]);
    choices.push(["copy", "Duplicate as a new draft", () => api("POST", `/api/todos/${t.id}/duplicate`).then(() => toast("Duplicated as a draft"))]);
    if (t.worktree) {
      choices.push(["code", "Open worktree in editor", () => api("POST", `/api/todos/${t.id}/open`).then(() => toast("Opening in your editor"))]);
      choices.push(["copy", `Copy branch name (${t.worktree.branch})`, () => copy(t.worktree.branch, "Branch name copied")]);
      choices.push(["copy", "Copy worktree path", () => copy(t.worktree.path, "Path copied")]);
    }
    choices.push(["trash", "Delete task", async () => {
      if (await ask({ title: "Delete this task?", body: "Its worktree and branch are removed too. This can't be undone.", ok: "Delete", danger: true })) {
        await api("DELETE", `/api/todos/${t.id}`);
        closeDetail();
        toast("Task deleted");
      }
    }]);
  }
  if (todoChat.history.length) choices.push(["x", "Clear this task's chat", () => api("DELETE", `/api/todos/${t.id}/chat`).then(() => { if (state.detail === t.id) todoChat.reset(); })]);
  if (!choices.length) return;
  await menu(choices);
}));

// The task chat already gives Claude the task's instructions and diff, and runs
// in its worktree; a project can replace this prompt in its settings.
const DEFAULT_REVIEW_PROMPT = `Review this task's changes as a strict senior reviewer, before they are merged. Don't modify any files.

Check, in this order:
1. Correctness: does it fully do what the instructions ask? Bugs, unhandled edge cases, regressions, callers that break.
2. Security and data loss risks.
3. Tests: are the changes covered where the project has tests? Run the relevant ones if you can.
4. Scope: unrelated changes, leftover debug code, dead code, code that doesn't match the surrounding style.

Read the surrounding code where you need to. Start with a one-line verdict, "Ready to merge" or "Needs changes", then list each must-fix issue with file:line and a concrete fix, then optional nice-to-haves. Leave out praise and anything you haven't verified.`;

let reviewNext = false;
function reviewTodo() {
  if (todoChat.busy) return toast("Wait for Claude to finish answering");
  reviewNext = true;
  const prompt = state.project?.review_prompt || DEFAULT_REVIEW_PROMPT;
  askChat(todoChat.input, $("#d-chat-form"), prompt, () => { state.pane = "chat"; renderPane(); });
}

async function reworkTodo(t) {
  const res = await ask({ title: "Send back for rework", body: "Claude continues in the same worktree with your notes. Paste or attach a screenshot to show what's wrong.", input: true, placeholder: "What should change?", ok: "Send back", attach: true });
  if (res === null) return;
  await api("POST", `/api/todos/${t.id}/rework`, { feedback: res.text, attachments: res.attachments });
  toast("Sent back for rework");
}

async function revertTodo(t) {
  if (t.status !== "merged" || t.revert) throw new Error("Only merged tasks can be reverted.");
  const pr = state.project?.merge_mode === "pr";
  const ok = await ask({
    title: `Revert "${title(t)}"?`,
    body: pr ? `Opens a pull request that undoes this change on ${state.project.default_branch}.`
      : `Adds a commit that undoes this change on ${state.project?.default_branch || "the default branch"}${state.project?.auto_push ? " and pushes it" : ""}. If later work conflicts, Claude gets a task to undo it by hand.`,
    ok: pr ? "Open revert PR" : "Revert", danger: true,
  });
  if (!ok) return;
  await api("POST", `/api/todos/${t.id}/revert`);
  toast("Reverting…");
}

// A small action sheet built on the ask dialog.
function menu(choices) {
  const d = $("#ask-sheet");
  $("#ask-title").textContent = "Actions";
  $("#ask-body").hidden = true;
  $("#ask-input").hidden = true;
  $("#ask-ok").hidden = true;
  const list = h("div", { class: "project-list" }, choices.map(([icon, label, fn]) => ib({
    type: "button", class: "btn", style: "width:100%;margin-bottom:8px",
    onclick: attempt(async () => { d.close(); await fn(); }),
  }, icon, label)));
  $("#ask-body").after(list);
  d.showModal();
  return new Promise((r) => d.addEventListener("close", () => { list.remove(); $("#ask-ok").hidden = false; r(); }, { once: true }));
}

$$(".segmented button").forEach((b) => b.addEventListener("click", () => { state.pane = b.dataset.pane; renderPane(); }));

function renderPane() {
  $$(".segmented button").forEach((b) => b.setAttribute("aria-selected", String(b.dataset.pane === state.pane)));
  $("#d-diff").hidden = state.pane !== "diff";
  $("#d-log").hidden = state.pane !== "log";
  $("#d-chat").hidden = state.pane !== "chat";
  renderDiff(state.diff);
}

function renderDiff(text) {
  const files = [];
  let cur = null;
  for (const line of text.split("\n")) {
    if (line.startsWith("diff --git")) {
      cur = { path: line.replace(/^diff --git a\/(.*) b\/.*$/, "$1"), lines: [], add: 0, del: 0 };
      files.push(cur);
    } else if (cur) {
      if (/^(index |new file|deleted file|similarity|rename |old mode|new mode|--- |\+\+\+ )/.test(line)) continue;
      if (line.startsWith("+")) cur.add++;
      else if (line.startsWith("-")) cur.del++;
      cur.lines.push(line);
    }
  }
  const add = files.reduce((n, f) => n + f.add, 0);
  const del = files.reduce((n, f) => n + f.del, 0);
  $("#d-diffstat").replaceChildren(...(files.length ? [h("span", { class: "plus" }, `+${add}`), " ", h("span", { class: "minus" }, `−${del}`)] : []));

  if (!files.length) {
    const t = state.todos.get(state.detail);
    const msg = text.startsWith("error:") ? text : t?.worktree ? "No changes compared to the default branch." : "Changes appear here once Claude has worked on this task.";
    $("#d-diff").replaceChildren(h("p", { class: "pane-empty" }, msg));
    return;
  }
  const commented = new Set(commentsFor(state.detail).map((c) => c.file));
  $("#d-diff").replaceChildren(...files.map((f) => h("details", {
    class: "diff-file", open: state.diffOpen.has(f.path) || commented.has(f.path),
    ontoggle: (e) => state.diffOpen[e.target.open ? "add" : "delete"](f.path),
  },
    h("summary", {}, h("span", { class: "path" }, f.path), h("span", { class: "counts" }, h("span", { class: "plus" }, `+${f.add}`), " ", h("span", { class: "minus" }, `−${f.del}`))),
    h("div", { class: "diff-lines" }, diffLines(f)))));
}

// Rows for one file, numbered like the new file (removed lines use old numbers),
// with saved review comments under their lines.
function diffLines(f) {
  const comments = commentsFor(state.detail).filter((c) => c.file === f.path);
  const rows = [];
  let oldLn = 0, newLn = 0;
  for (const l of f.lines) {
    const hunk = /^@@ -(\d+)(?:,\d+)? \+(\d+)/.exec(l);
    if (hunk) {
      oldLn = Number(hunk[1]); newLn = Number(hunk[2]);
      rows.push(h("div", { class: "hunk" }, l));
      continue;
    }
    if (l.startsWith("\\")) { rows.push(h("div", { class: "meta" }, l)); continue; }
    const side = l.startsWith("-") ? "old" : "new";
    const ln = side === "old" ? oldLn++ : newLn++;
    if (l.startsWith(" ") || l === "") oldLn++;
    rows.push(h("div", { class: l.startsWith("+") ? "add" : l.startsWith("-") ? "del" : "", "data-ln": ln, "data-side": side, "data-file": f.path, title: "Click to comment" }, l || " "));
    for (const c of comments.filter((c) => c.line === ln && c.side === side)) {
      rows.push(h("div", { class: "comment" },
        h("span", {}, c.text),
        ib({ class: "link", type: "button", "aria-label": "Delete comment", onclick: () => {
          state.comments[state.detail] = commentsFor(state.detail).filter((x) => x !== c);
          saveComments(); renderPane(); renderActions(state.todos.get(state.detail));
        } }, "trash", "Delete")));
    }
  }
  return rows;
}

// ------------------------------------------------------------------ notifications & tab title
const notifyOn = () => { try { return localStorage.getItem("dash.notify") === "1"; } catch { return false; } };
function notify(what, t, detail = "") {
  if (!notifyOn() || !("Notification" in window) || Notification.permission !== "granted") return;
  if (document.visibilityState === "visible" && document.hasFocus()) return; // the page already shows it
  const n = new Notification(`${what}: ${title(t)}`, { body: detail || "", tag: `dash-${t.id}`, silent: false });
  n.onclick = () => { window.focus(); showView("board"); openDetail(t.id); n.close(); };
}
async function toggleNotifications() {
  if (!("Notification" in window)) throw new Error("This browser doesn't support notifications.");
  if (notifyOn()) {
    try { localStorage.setItem("dash.notify", "0"); } catch {}
    toast("Notifications off");
  } else {
    const perm = await Notification.requestPermission();
    if (perm !== "granted") throw new Error("Notifications are blocked for this site in your browser settings.");
    try { localStorage.setItem("dash.notify", "1"); } catch {}
    toast("Notifications on: you'll hear about reviews, failures and approvals while Dash is in the background");
  }
  renderProjectList();
}
// Tab title shows how many things wait for you: reviews + permission requests.
function updateNeedsYou(items) {
  const n = (items?.review?.length || 0) + state.perms.length;
  document.title = n ? `(${n}) Dash` : "Dash";
}

// ------------------------------------------------------------------ search (/)
function openSearch() {
  showView("board");
  $("#search-bar").hidden = false;
  const input = $("#search-input");
  input.focus();
  input.select();
}
function syncSearchBar() {
  const bar = $("#search-bar");
  if (state.query && bar.hidden) bar.hidden = false;
  if (document.activeElement !== $("#search-input")) $("#search-input").value = state.query;
  const n = Object.values(laneItems()).reduce((a, l) => a + l.length, 0);
  $("#search-count").textContent = state.query ? `${n} ${n === 1 ? "match" : "matches"}` : "";
}
function clearSearch() {
  state.query = "";
  $("#search-input").value = "";
  $("#search-bar").hidden = true;
  renderBoard();
}
$("#search-input").addEventListener("input", (e) => { state.query = e.target.value; keys.cur.row = 0; renderBoard(); });
$("#search-input").addEventListener("keydown", (e) => {
  if (e.key === "Enter") { e.preventDefault(); e.target.blur(); jumpMatch(1, true); }
  if (e.key === "Escape") { e.preventDefault(); clearSearch(); e.target.blur(); }
});
$("#search-clear").addEventListener("click", clearSearch);
$("#search-open").addEventListener("click", openSearch);

// n / N: next/previous match in lane order
function jumpMatch(dir, fromStart = false) {
  const flat = [];
  LANES.forEach((l, li) => laneTodos(li).forEach((t, ri) => flat.push([li, ri])));
  if (!flat.length) return toast("No matches");
  let i = fromStart ? 0 : flat.findIndex(([li, ri]) => li === keys.cur.lane && ri === keys.cur.row);
  if (!fromStart) i = (i + dir + flat.length) % flat.length;
  moveCursor(...flat[Math.max(0, i)]);
}

// ------------------------------------------------------------------ diff comments
function commentsFor(id) { return state.comments[id] || []; }

$("#d-diff").addEventListener("click", (e) => {
  const line = e.target.closest(".diff-lines > div[data-ln]");
  const t = state.todos.get(state.detail);
  if (!line || !t || !["review", "failed"].includes(t.status)) return;
  if (line.nextElementSibling?.classList.contains("comment-box")) return;
  const box = h("form", { class: "comment-box" },
    h("textarea", { rows: 3, placeholder: "What should Claude change here?", "aria-label": "Comment on this line" }),
    h("div", { class: "comment-actions" },
      ib({ type: "button", class: "btn", onclick: () => box.remove() }, "x", "Cancel"),
      ib({ class: "btn primary" }, "comment", "Add comment")));
  box.addEventListener("submit", (ev) => {
    ev.preventDefault();
    const text = box.querySelector("textarea").value.trim();
    if (!text) return box.remove();
    state.comments[t.id] = [...commentsFor(t.id), { file: line.dataset.file, line: Number(line.dataset.ln), side: line.dataset.side, code: line.textContent, text }];
    saveComments();
    renderPane();
    renderActions(t);
  });
  box.querySelector("textarea").addEventListener("keydown", (ev) => {
    if (ev.ctrlKey && ev.key === "Enter") box.requestSubmit();
    if (ev.key === "Escape") { ev.stopPropagation(); box.remove(); }
  });
  line.after(box);
  box.querySelector("textarea").focus();
});

function commentFeedback(list, extra) {
  const parts = list.map((c) => `### ${c.file}, ${c.side === "old" ? "removed line" : "line"} ${c.line}\n> ${c.code}\n\n${c.text}`);
  return `Review comments on your diff:\n\n${parts.join("\n\n")}${extra ? `\n\nAlso: ${extra}` : ""}`;
}

async function sendComments(t) {
  const list = commentsFor(t.id);
  const extra = await ask({ title: `Send ${list.length} ${list.length === 1 ? "comment" : "comments"} to Claude`, body: "Claude continues in the same worktree and addresses each comment.", input: true, placeholder: "Anything else? (optional)", ok: "Send for rework" });
  if (extra === null) return;
  await api("POST", `/api/todos/${t.id}/rework`, { feedback: commentFeedback(list, extra) });
  delete state.comments[t.id];
  saveComments();
  toast("Comments sent for rework");
}

// ------------------------------------------------------------------ tests (checks)
function renderChecks(t) {
  const box = $("#d-checks");
  const c = t.checks;
  box.hidden = !c;
  if (!c) return;
  const st = $("#d-checks-state");
  st.className = `checks-state ${c.passed ? "pass" : "fail"}`;
  st.textContent = c.passed ? "Tests pass" : `Tests fail (exit ${c.exit_code})`;
  const when = c.stage === "merge" ? `after merging ${state.project?.default_branch || "main"}` : "before review";
  $("#d-checks-meta").textContent = `${when} · ${Math.round(c.duration_s)}s`;
  $("#d-checks-output").textContent = `$ ${c.command}\n\n${c.output || "No output."}`;
  if (!c.passed && box.dataset.todo !== t.id) box.open = true;
  box.dataset.todo = t.id;
}

// ------------------------------------------------------------------ permission requests
function describePerm(p) {
  const i = p.input || {};
  switch (p.tool) {
    case "Bash": return { title: "run a command", detail: i.command, note: i.description };
    case "Write": case "Edit": case "MultiEdit": case "NotebookEdit": return { title: `edit ${i.file_path || i.notebook_path || "a file"}`, detail: i.file_path };
    case "WebFetch": return { title: "fetch a web page", detail: i.url };
    case "WebSearch": return { title: "search the web", detail: i.query };
    default: return { title: `use ${p.tool}`, detail: JSON.stringify(i, null, 2) };
  }
}

function permCard(p, withTodo) {
  const d = describePerm(p);
  const t = state.todos.get(p.todo_id);
  const decide = (decision) => attempt(async () => {
    await api("POST", `/api/permissions/${p.id}`, { decision });
    toast(decision === "deny" ? "Denied" : decision === "always" ? `${p.tool} always allowed in this project` : "Allowed");
  });
  return h("div", { class: "perm", role: "group", "aria-label": `Permission request: ${d.title}` },
    h("p", { class: "perm-q" }, `Claude wants to ${d.title}`,
      withTodo && t ? h("span", { class: "todo-ref" }, ` · ${title(t)}`) : null),
    d.note ? h("p", { class: "hint", style: "margin:0" }, d.note) : null,
    d.detail ? h("code", { class: "perm-cmd" }, d.detail) : null,
    h("div", { class: "perm-actions" },
      ib({ class: "btn allow", onclick: decide("allow") }, "check", "Allow"),
      ib({ class: "btn", onclick: decide("always") }, "checks", `Always allow ${p.tool}`),
      ib({ class: "btn danger", onclick: decide("deny") }, "x", "Deny"),
      withTodo && t ? ib({ class: "link", onclick: () => openDetail(t.id) }, "right", "Open task") : null));
}

function renderPerms() {
  const banner = $("#perm-banner");
  banner.hidden = !state.perms.length;
  banner.replaceChildren(...state.perms.map((p) => permCard(p, true)));
  const mine = state.perms.filter((p) => p.todo_id === state.detail);
  $("#d-perms").hidden = !mine.length;
  $("#d-perms").replaceChildren(...mine.map((p) => permCard(p, false)));
  renderBoard();
}

// ------------------------------------------------------------------ usage & queue
async function loadUsage() {
  state.usage = await api("GET", "/api/usage");
  renderUsage();
}

const windowLabel = (n) => ({ five_hour: "5-hour window", seven_day: "Weekly", seven_day_opus: "Weekly (Opus)" })[n] || n;
const shortLabel = (n) => ({ five_hour: "5h", seven_day: "7d", seven_day_opus: "7d Opus" })[n] || n;
const fmtTime = (iso) => {
  const d = new Date(iso);
  const sameDay = d.toDateString() === new Date().toDateString();
  return sameDay ? d.toLocaleTimeString(timeLocale, { hour: "2-digit", minute: "2-digit" }) : d.toLocaleString(timeLocale, { weekday: "short", hour: "2-digit", minute: "2-digit" });
};
const windowHours = { five_hour: 5, seven_day: 168, seven_day_opus: 168 };
// Share of the window elapsed since its last reset (0..1), or null for an unknown window length.
const windowElapsed = (w) => {
  const hours = windowHours[w.name];
  if (!hours) return null;
  const span = hours * 3600000;
  return Math.min(1, Math.max(0, (span - (new Date(w.resets_at) - Date.now())) / span));
};

function renderUsage() {
  const u = state.usage;
  const pill = $("#usage-pill");
  if (!u || (!u.known && !u.manual_pause)) { pill.hidden = true; return; }
  pill.hidden = false;
  const live = (u.windows || []).filter((w) => new Date(w.resets_at) > new Date());
  const top = live.reduce((a, w) => (!a || w.utilization > a.utilization ? w : a), null);
  const overPace = (w) => { const e = windowElapsed(w); return e !== null && w.utilization > e; };
  pill.className = `usage-pill${u.paused ? " paused" : top && (top.utilization >= 0.7 || overPace(top)) ? " warn" : ""}`;
  pill.title = u.paused ? u.reason : top && overPace(top) ? "Claude subscription usage, ahead of pace" : "Claude subscription usage";

  const reason = u.paused
    ? `${u.reason}. No new tasks start${u.until && !u.manual_pause ? ` until ${fmtTime(u.until)}` : ""}; running ones finish.`
    : "Tasks start normally.";
  const meter = (w, compact) => {
    const pct = Math.round(w.utilization * 100);
    const cls = w.utilization >= (u.pause_at || 1) ? "full" : w.utilization >= 0.7 ? "warn" : "";
    const elapsed = windowElapsed(w);
    const pace = elapsed === null ? null : Math.round(elapsed * 100);
    const fill = Math.min(100, pct);
    const paceText = pace === null ? null : pct > pace ? `${pct - pace} points ahead of pace` : `${pace - pct} points under pace`;
    return h("div", {},
      h("div", { class: "meter-head" },
        h("span", {}, compact ? shortLabel(w.name) : windowLabel(w.name)),
        h("span", {}, compact ? `${pct}%` : `${pct}% · resets ${fmtTime(w.resets_at)}`)),
      h("div", { class: `meter ${cls}`, role: "meter", "aria-valuenow": pct, "aria-valuemin": 0, "aria-valuemax": 100, "aria-label": windowLabel(w.name) },
        h("span", { style: `width:${fill}%` }),
        pace !== null && fill > pace ? h("b", { class: "over", style: `left:${pace}%;width:${fill - pace}%` }) : null,
        pace !== null ? h("i", { class: "mark pace", style: `left:${pace}%`, title: `${pace}% of the window elapsed` }) : null,
        u.pause_at > 0 && u.pause_at < 1 ? h("i", { class: "mark", style: `left:${u.pause_at * 100}%`, title: "Queue pauses here" }) : null),
      compact
        ? h("div", { class: `meter-pace${pace !== null && pct > pace ? " over" : ""}` },
          `resets ${fmtTime(w.resets_at)}`, paceText ? ` · ${pct > pace ? `+${pct - pace}` : `−${pace - pct}`} vs pace` : null)
        : pace !== null ? h("div", { class: `meter-pace${pct > pace ? " over" : ""}` }, paceText, ` · ${pace}% of window elapsed`) : null);
  };
  const pie = (w) => {
    const pct = Math.round(w.utilization * 100);
    const cls = w.utilization >= (u.pause_at || 1) ? " full" : w.utilization >= 0.7 ? " warn" : "";
    const elapsed = windowElapsed(w);
    const pace = elapsed === null ? null : Math.round(elapsed * 100);
    return h("span", { class: "pie-wrap", title: `${windowLabel(w.name)}: ${pct}%${pace !== null ? ` (${pace}% of window elapsed)` : ""} · resets ${fmtTime(w.resets_at)}` },
      h("span", { class: `pie${cls}${pace !== null ? " paced" : ""}`, style: `--p:${Math.min(100, pct)};--e:${pace ?? 0}`, role: "img", "aria-label": `${windowLabel(w.name)} ${pct}%` },
        h("b", {}, pct)),
      h("small", {}, shortLabel(w.name)));
  };
  pill.replaceChildren(
    h("span", { class: "usage-pies" }, live.map(pie)),
    h("span", { class: "usage-sum" }, u.paused ? "Queue paused" : top ? `${shortLabel(top.name)} ${Math.round(top.utilization * 100)}%${overPace(top) ? " ▲" : ""}` : "Usage"),
    h("span", { class: "usage-detail" },
      h("span", { class: "usage-head" }, h("span", {}, "Claude usage"), h("span", {}, u.paused ? "Paused" : "Queue running")),
      u.paused ? h("span", { class: "usage-reason" }, reason) : null,
      live.map((w) => meter(w, true))));

  $("#usage-reason").textContent = reason;
  $("#usage-meters").replaceChildren(...live.map((w) => meter(w, false)));
  $("#usage-note").textContent = u.pause_at > 0 && u.pause_at < 1
    ? `The queue pauses automatically at ${Math.round(u.pause_at * 100)}% of any window.`
    : "The queue pauses automatically when a window's limit is reached.";
  setLabel($("#queue-toggle"), u.manual_pause ? "play" : "pause", u.manual_pause ? "Resume queue" : "Pause queue");
  $("#queue-toggle").className = `btn ${u.manual_pause ? "primary" : ""}`;
}

$("#usage-pill").addEventListener("click", () => { renderUsage(); $("#usage-sheet").showModal(); });
$("#queue-toggle").addEventListener("click", attempt(async () => {
  state.usage = await api("POST", state.usage?.manual_pause ? "/api/queue/resume" : "/api/queue/pause");
  renderUsage();
  toast(state.usage.manual_pause ? "Queue paused" : "Queue resumed");
}));

// ------------------------------------------------------------------ GitHub Actions
const CI_LABEL = { passing: "Build passing", failing: "Build failing", running: "Build running", none: "No builds yet", unknown: "Builds unavailable" };
async function loadCI() {
  const id = state.project?.id;
  if (!id || !state.project.remote_url) return;
  const st = await api("GET", `/api/projects/${id}/ci`);
  if (state.project?.id === id) { state.ci = st; renderCI(); }
}

function runState(r) {
  if (r.status !== "completed") return ["running", "Running"];
  return { success: ["passing", "Passed"], failure: ["failing", "Failed"], timed_out: ["failing", "Timed out"],
    startup_failure: ["failing", "Couldn't start"], cancelled: ["muted", "Cancelled"], skipped: ["muted", "Skipped"] }[r.conclusion] || ["muted", r.conclusion];
}

function renderCI() {
  const st = state.ci;
  const pill = $("#ci-pill");
  const show = !!(state.project?.remote_url && st && st.state !== "unknown" && st.state !== "none") || st?.state === "failing";
  pill.hidden = !show;
  if (st) {
    pill.className = `usage-pill ci-pill ci-${st.state}`;
    pill.textContent = CI_LABEL[st.state];
    pill.title = CI_LABEL[st.state];
  }
  if (!st) return;
  const fix = st.todo_id && state.todos.get(st.todo_id);
  $("#ci-summary").replaceChildren(
    `${CI_LABEL[st.state]} on ${st.branch || "the default branch"}`,
    st.sha ? ` at ${st.sha.slice(0, 8)}` : "", ". ",
    st.error ? h("span", { class: "err-text" }, st.error) : `Checked ${ago(st.checked) === "now" ? "just now" : `${ago(st.checked)} ago`}.`,
    fix ? h("span", { class: "ci-fix" }, " Claude is fixing it: ", ib({ type: "button", class: "link inline", onclick: () => { $("#ci-sheet").close(); openDetail(fix.id); } }, "right", title(fix))) : "");
  $("#ci-runs").replaceChildren(...(st.runs || []).slice(0, 12).map((r) => {
    const [cls, label] = runState(r);
    return h("li", {}, h("a", { class: `run run-${cls}`, href: r.url, target: "_blank", rel: "noopener" },
      h("span", { class: "run-dot", "aria-hidden": "true" }),
      h("span", { class: "run-main" }, h("strong", {}, r.workflow), h("span", { class: "run-title" }, r.title)),
      h("span", { class: "run-side" }, label, h("span", { class: "run-sha" }, `${r.sha.slice(0, 7)} · ${ago(r.created_at)}`))));
  }));
  $("#ci-investigate").hidden = !(st.state === "failing" && !fix);
}

async function openCI() {
  if (!state.project) throw new Error("Select a project first (p).");
  if (!state.project.remote_url) throw new Error("Connect a GitHub repository first (Projects → Create GitHub repository).");
  if (!state.ci) await loadCI();
  renderCI();
  $("#ci-sheet").showModal();
}
$("#ci-pill").addEventListener("click", attempt(openCI));
$("#ci-refresh").addEventListener("click", attempt(async () => {
  state.ci = await api("POST", `/api/projects/${state.project.id}/ci/refresh`);
  renderCI();
  toast("Builds checked");
}));
$("#ci-investigate").addEventListener("click", attempt(async () => {
  const t = await api("POST", `/api/projects/${state.project.id}/ci/investigate`);
  $("#ci-sheet").close();
  toast(`Queued: ${title(t)}`);
}));

// ------------------------------------------------------------------ project settings
function openSettings() {
  const p = state.project;
  const f = $("#settings-form");
  f.test_command.value = p.test_command || "";
  f.max_auto_fixes.value = p.max_auto_fixes ?? 2;
  f.setup_command.value = p.setup_command || "";
  f.copy_files.value = (p.copy_files || []).join("\n");
  f.allowed_tools.value = (p.allowed_tools || []).join("\n");
  f.chat_permission_mode.value = p.chat_permission_mode || "";
  f.review_prompt.value = p.review_prompt || "";
  f.review_prompt.placeholder = DEFAULT_REVIEW_PROMPT;
  f.run_command.value = p.run_command || "";
  f.deploy_command.value = p.deploy_command || "";
  f.auto_push.checked = !!p.auto_push;
  f.auto_approve.checked = !!p.auto_approve;
  f.merge_mode.value = p.merge_mode || "local";
  f.investigate_ci.checked = p.investigate_ci !== false;
  f.max_run_minutes.value = p.max_run_minutes || "";
  f.max_turns.value = p.max_turns || "";
  f.use_color.checked = !!p.color;
  f.color.value = p.color || "#8aa4ff";
  f.color.disabled = !p.color;
  f.icon.value = p.icon || "";
  projectIcon(p, $("#settings-icon"));
  syncMergeHint();
  $("#settings-sheet").returnValue = "";
  $("#settings-sheet").showModal();
}
function syncMergeHint() {
  const f = $("#settings-form");
  const p = state.project;
  const pr = f.merge_mode.value === "pr";
  $("#auto-push-row").hidden = pr;
  $("#merge-hint").textContent = !p.remote_url
    ? "Connect a GitHub repository (Projects → Create GitHub repository) to push or open pull requests."
    : pr ? `Dash pushes the task's branch and opens a pull request against ${p.default_branch}. Merge it on GitHub.`
      : f.auto_push.checked ? `Before each merge Dash pulls ${p.default_branch} from GitHub, so pushes don't get rejected.` : "";
}
$("#settings-form").addEventListener("change", syncMergeHint);
$("#settings-form").use_color.addEventListener("change", (e) => { e.target.form.color.disabled = !e.target.checked; });
$("#settings-form").color.addEventListener("input", (e) => { e.target.form.use_color.checked = true; });
const settingsIcon = (icon) => {
  $("#settings-form").icon.value = icon;
  projectIcon({ ...state.project, icon }, $("#settings-icon"));
};
$("#settings-icon-pick").addEventListener("click", () => $("#settings-icon-file").click());
$("#settings-icon-clear").addEventListener("click", () => settingsIcon(""));
$("#settings-icon-file").addEventListener("change", attempt(async (e) => {
  const file = e.target.files[0];
  e.target.value = "";
  if (!file) return;
  const a = await uploadFile(file, state.project.prefix || "");
  if (!a.type.startsWith("image/")) throw new Error("Choose a PNG, JPEG, GIF, WebP or SVG image.");
  settingsIcon(`${a.id}/${a.name}`);
}));
$("#settings-sheet").addEventListener("close", attempt(async () => {
  if ($("#settings-sheet").returnValue !== "save") return;
  const f = $("#settings-form");
  const old = state.project;
  const saved = await api("PATCH", `/api/projects/${old.id}`, {
    test_command: f.test_command.value.trim(),
    max_auto_fixes: Math.max(0, Number(f.max_auto_fixes.value) || 0),
    setup_command: f.setup_command.value.trim(),
    copy_files: f.copy_files.value.split("\n").map((x) => x.trim()).filter(Boolean),
    allowed_tools: f.allowed_tools.value.split("\n").map((x) => x.trim()).filter(Boolean),
    chat_permission_mode: f.chat_permission_mode.value,
    review_prompt: f.review_prompt.value.trim(),
    run_command: f.run_command.value.trim(),
    deploy_command: f.deploy_command.value.trim(),
    auto_push: f.auto_push.checked,
    auto_approve: f.auto_approve.checked,
    merge_mode: f.merge_mode.value,
    investigate_ci: f.investigate_ci.checked,
    max_run_minutes: Number(f.max_run_minutes.value) || 0,
    max_turns: Number(f.max_turns.value) || 0,
    color: f.use_color.checked ? f.color.value : "",
    icon: f.icon.value,
  });
  // Keep the client-only fields, and the list entry in step for its color and icon.
  state.project = { ...saved, machine: old.machine, prefix: old.prefix };
  state.projects = state.projects.map((x) => (x === old ? state.project : x));
  renderProjectHeader();
  renderProjectList();
  renderBoard(); // auto approve shows or hides Review
  toast("Settings saved");
}));

// ------------------------------------------------------------------ chat
// makeChat drives one conversation UI: a log, its empty state and a composer.
// target() names where it runs ({prefix, ...fields sent with each turn});
// clear() deletes its saved conversation.
// The client owns the history and sends it in full each turn; the server saves
// every finished turn.
function makeChat({ log, empty, form, target, actions, cwd, clear, scroller = () => log, saved = () => {} }) {
  const c = { history: [], current: null, ws: null, prefix: "" };
  const input = form.q;
  const sendBtn = form.querySelector("button");
  const finish = () => { c.current = null; sendBtn.disabled = false; };
  const toEnd = () => { if (log.offsetParent) scroller().scrollTop = scroller().scrollHeight; };
  const assistant = (content) => h("div", { class: "msg assistant" }, h("div", { class: "reply", innerHTML: renderMarkdown(content) }), actions(content));
  const prefixOf = () => target().prefix || "";
  const user = (m) => h("div", { class: "msg user" }, m.content,
    m.attachments?.length ? h("div", { class: "msg-attach" }, ...m.attachments.map((a) => attachThumb(a, null, prefixOf()))) : null);
  // Images and files dropped onto the chat or pasted into its text field.
  const attachRow = h("div", { class: "attach", hidden: true });
  form.prepend(attachRow);
  const att = attachBox(attachRow, input, () => {}, { zone: form.parentElement, compact: true, prefix: prefixOf });

  function socket(prefix) {
    if (c.ws && c.ws.readyState <= 1 && c.prefix === prefix) return c.ws;
    c.ws?.close();
    const ws = c.ws = new WebSocket(wsURL(on(prefix, "/ws/chat")));
    c.prefix = prefix;
    ws.onmessage = (m) => {
      const d = JSON.parse(m.data);
      d.text ??= ""; // omitted when empty
      // An abandoned socket (see reset) finishes its reply so the server saves it.
      if (ws !== c.ws) {
        // Nobody sees its approval requests any more.
        if (d.kind === "permission") ws.send(JSON.stringify({ type: "permission", id: d.id, decision: "deny" }));
        if (d.kind === "done" || d.kind === "error") { ws.close(); if (d.kind === "done") saved(ws.fields); }
        return;
      }
      if (d.kind === "cwd" && cwd) { cwd.hidden = false; cwd.textContent = cwd.title = `Runs in ${d.text}`; }
      const cur = c.current;
      if (!cur) return;
      if (d.kind === "thinking") cur.thinking.textContent += d.text;
      else if (d.kind === "text") { cur.content += d.text; cur.seg += d.text; cur.reply.innerHTML = renderMarkdown(cur.seg); }
      else if (d.kind === "tool_use") {
        // Later text goes below the tool call, in a reply of its own.
        const out = h("pre", { class: "tool-out", hidden: true });
        const el = h("details", { class: "tool" }, h("summary", {}, h("b", {}, d.tool), ` ${toolSummary(d.tool, d.input)}`),
          h("pre", { class: "tool-in" }, toolDetail(d.tool, d.input)), out);
        cur.tools.set(d.id, { el, out });
        cur.reply.after(el);
        cur.reply = h("div", { class: "reply" });
        el.after(cur.reply);
        cur.seg = "";
      } else if (d.kind === "tool_result") {
        const t = cur.tools.get(d.id);
        if (t) { t.out.hidden = false; t.out.textContent = d.text || "(no output)"; t.el.classList.toggle("error", !!d.is_error); }
      } else if (d.kind === "permission") {
        cur.reply.before(chatPermCard(d, (decision) => ws.send(JSON.stringify({ type: "permission", id: d.id, decision }))));
      } else if (d.kind === "permission_decided") {
        const st = log.querySelector(`.perm[data-id="${d.id}"] .perm-actions`);
        st?.replaceChildren(h("span", { class: "perm-status" }, { allow: "Approved", deny: "Denied", timeout: "Not answered in time: denied" }[d.text] || d.text));
      }
      else if (d.kind === "error") { cur.el.classList.add("error"); cur.reply.append(h("p", {}, d.text)); }
      if (d.kind === "done" || d.kind === "error") {
        cur.el.classList.remove("pending");
        if (cur.content) cur.el.append(actions(cur.content));
        if (cur.content) c.history.push({ role: "assistant", content: cur.content });
        else c.history.pop(); // keep history alternating
        finish();
      }
      const sc = scroller();
      if (sc.scrollHeight - sc.scrollTop - sc.clientHeight < 120) toEnd();
    };
    ws.onclose = () => {
      if (ws !== c.ws || !c.current) return;
      c.current.el.classList.remove("pending");
      c.current.reply.textContent ||= "Connection lost. Send your message again.";
      c.history.pop();
      finish();
    };
    return ws;
  }

  // reset shows another (or a cleared) conversation. A reply still streaming
  // is left to finish on its own socket.
  function reset(saved = []) {
    if (c.current) { c.ws = null; finish(); }
    c.history = [...saved];
    empty.hidden = saved.length > 0;
    log.replaceChildren(empty, ...saved.map((m) => m.role === "user" ? user(m) : assistant(m.content)));
    toEnd();
  }

  function send(q, attachments = []) {
    empty.hidden = true;
    const m = { role: "user", content: q, ...(attachments.length ? { attachments } : {}) };
    c.history.push(m);
    const thinking = h("div", { class: "thinking" });
    const reply = h("div", { class: "reply" });
    const el = h("div", { class: "msg assistant pending" }, thinking, reply);
    log.append(user(m), el);
    toEnd();
    c.current = { el, thinking, reply, content: "", seg: "", tools: new Map() };
    sendBtn.disabled = true;
    const { prefix = "", ...fields } = target();
    const ws = socket(prefix);
    ws.fields = fields;
    const go = () => ws.send(JSON.stringify({ type: "send", ...fields, messages: c.history }));
    ws.readyState === 1 ? go() : ws.addEventListener("open", go, { once: true });
  }

  // Slash commands run here instead of going to Claude. Anything else starting
  // with "/" (a path, say) is sent as a message.
  const commands = {
    clear: async () => { await clear(); reset(); },
    help: () => toast("/clear starts a new conversation. /help shows this.", { head: "Chat commands" }),
  };
  commands.new = commands.reset = commands.clear;

  const autoGrow = () => { input.style.height = "auto"; input.style.height = `${input.scrollHeight}px`; };
  input.addEventListener("input", autoGrow);
  form.addEventListener("submit", attempt(async (e) => {
    e.preventDefault();
    if (c.current) return;
    await att.settled();
    const q = input.value.trim(), files = att.items();
    if ((!q && !files.length) || c.current) return;
    const cmd = /^\/(\w+)$/.exec(q)?.[1].toLowerCase();
    input.value = "";
    autoGrow();
    if (!files.length && Object.hasOwn(commands, cmd)) return commands[cmd]();
    att.reset();
    send(q, files);
  }));
  input.addEventListener("keydown", (e) => {
    // Enter sends on devices with a hardware keyboard; on touch keyboards Enter adds a line.
    if (e.key === "Enter" && !e.shiftKey && !matchMedia("(pointer: coarse)").matches) {
      e.preventDefault();
      form.requestSubmit();
    }
  });

  return { reset, input, clear: commands.clear, get history() { return c.history; }, get busy() { return !!c.current; } };
}

// Tool calls in the chat: a one-line summary, and the full input when expanded.
function toolSummary(tool, i = {}) {
  const s = i.command ?? i.file_path ?? i.pattern ?? i.path ?? "";
  return String(s).split("\n")[0];
}
function toolDetail(tool, i = {}) {
  const lines = (s, p) => String(s ?? "").split("\n").map((l) => p + l).join("\n");
  switch (tool) {
    case "Bash": return i.command;
    case "Edit": return `${i.file_path}\n${lines(i.old_string, "- ")}\n${lines(i.new_string, "+ ")}`;
    case "Write": return `${i.file_path}\n${i.content}`;
    default: return JSON.stringify(i, null, 2);
  }
}

// An approval request from the chat, answered over its own socket.
function chatPermCard(p, decide) {
  const d = describePerm(p);
  const answer = (decision) => (e) => {
    e.currentTarget.parentElement.querySelectorAll("button").forEach((b) => { b.disabled = true; });
    decide(decision);
  };
  return h("div", { class: "perm", role: "group", "aria-label": `Permission request: ${d.title}`, "data-id": p.id },
    h("p", { class: "perm-q" }, `Claude wants to ${d.title}`),
    d.note ? h("p", { class: "hint", style: "margin:0" }, d.note) : null,
    h("code", { class: "perm-cmd" }, toolDetail(p.tool, p.input || {})),
    h("div", { class: "perm-actions" },
      ib({ class: "btn allow", onclick: answer("allow") }, "check", "Approve"),
      ib({ class: "btn danger", onclick: answer("deny") }, "x", "Deny")));
}

// key: the project a project chat is about; its tasks go there even when another project is selected.
const chatActions = (pick, key) => (answer) => h("div", { class: "msg-actions" },
  ib({ class: "link", onclick: () => {
    pick ||= !!key && key !== projectKey(state.project);
    if (!(pick ? state.projects?.length : state.project)) return toast(pick ? "Create a project first" : "Select a project first", true);
    openTodoForm(null, { pick });
    if (key && pick) $("#todo-form").project.value = key;
    $("#todo-form").prompt.value = answer;
  } }, "plus", "Make this a task"),
  ib({ class: "link", onclick: () => copy(answer, "Copied") }, "copy", "Copy"));

// The global chat isn't about any project: it runs in the home directory of this machine.
const chat = makeChat({
  log: $("#chat-log"), empty: $("#chat-empty"), form: $("#chat-form"),
  target: () => ({}),
  clear: () => api("DELETE", "/api/chat"),
  actions: chatActions(true),
  cwd: $("#chat-cwd"),
});

// The server saves every finished turn, so the conversation survives restarts.
async function loadChat() {
  const saved = await api("GET", "/api/chat");
  if (saved.length && !chat.history.length && !chat.busy) chat.reset(saved);
}
loadChat().catch((e) => toast(`Couldn't load chat history: ${e.message}`, true));

// A conversation about the open todo, run on the todo's computer. Claude sees
// the todo's instructions, so a draft can be talked into a better prompt.
const EDITABLE = ["draft", "queued", "failed"];
const todoChat = makeChat({
  log: $("#d-chat-log"), empty: $("#d-chat-empty"), form: $("#d-chat-form"),
  // reviewNext marks the turn the Review button sends, which locks the task until it ends.
  target: () => { const review = reviewNext; reviewNext = false; return { prefix: here(), todo: state.detail, ...(review && { review }) }; },
  clear: () => api("DELETE", `/api/todos/${state.detail}/chat`),
  scroller: () => $(".detail-body"),
  cwd: $("#d-chat-cwd"),
  // A turn left streaming when its todo was closed is saved when it finishes.
  saved: ({ todo }) => { if (todo === state.detail && !todoChat.busy) loadTodoChat().catch(fail); },
  actions: (answer) => {
    const t = state.todos.get(state.detail);
    return h("div", { class: "msg-actions" },
      t && EDITABLE.includes(t.status) ? ib({ class: "link", onclick: attempt(async () => {
        if (!await ask({ title: "Replace the instructions?", body: "This answer becomes the task's instructions for Claude.", ok: "Replace" })) return;
        await api("PATCH", `/api/todos/${t.id}`, { prompt: answer });
        toast("Instructions updated");
      }) }, "draft", "Use as instructions") : null,
      t?.worktree && ["review", "failed"].includes(t.status) ? ib({ class: "link", onclick: attempt(async () => {
        if (!await ask({ title: "Send back for rework?", body: "Claude continues in the same worktree with this answer as feedback.", ok: "Send back" })) return;
        await api("POST", `/api/todos/${t.id}/rework`, { feedback: answer });
        toast("Sent back for rework");
      }) }, "redo", "Send back as rework") : null,
      ib({ class: "link", onclick: () => copy(answer, "Copied") }, "copy", "Copy"));
  },
});

// ------------------------------------------------------------------ chat pane
// One pane on the right holds every chat but the task chats: General, the
// selected project's ("This project") and project chats kept as tabs. Each chat
// has its own controller, so a reply keeps streaming while another tab is shown
// or the pane is closed; the pane only switches which one is visible.
// Overlay (default) floats over the content; pinned takes a grid column, but
// only on wide screens. On mobile it is a full-screen sheet.
const wide = matchMedia("(min-width: 1280px)");
const CHAT_MIN_W = 280;
const pane = (() => {
  const get = (k) => { try { return localStorage.getItem(k); } catch { return null; } };
  const base = { open: false, pinned: false, width: null, tab: null, tabs: [] };
  try { const s = JSON.parse(get("dash.chatPane")); if (s) return { ...base, ...s }; } catch {}
  // Carry over the board chat's settings: it pushed the board aside, like pinned.
  const old = get("dash.boardChat");
  let tabs = [];
  try { tabs = JSON.parse(get("dash.chatTabs") || "[]"); } catch {}
  return { ...base, open: old === "1", pinned: old != null, width: Number(get("dash.boardChatW")) || null, tab: old === "1" ? "project" : null, tabs };
})();
function savePane() {
  try {
    localStorage.setItem("dash.chatPane", JSON.stringify(pane));
    ["dash.boardChat", "dash.chatTabs", "dash.boardChatW"].forEach((k) => localStorage.removeItem(k));
  } catch {}
}
savePane();
const paneOverlays = () => !pane.pinned || !wide.matches;

// Project chats, created on first use. key: projectKey.
const projectChats = new Map();
const projectByKey = (key) => state.projects?.find((p) => projectKey(p) === key) || null;
function projectChatFor(p) {
  const key = projectKey(p);
  if (projectChats.has(key)) return projectChats.get(key);
  const proj = () => projectByKey(key) || p;
  const panel = $("#project-chat-tpl").content.firstElementChild.cloneNode(true);
  panel.dataset.chat = key;
  $("#chat-pane").append(panel);
  const pc = { panel, loaded: false };
  pc.chat = makeChat({
    log: panel.querySelector(".chat-log"), empty: panel.querySelector(".chat-empty"), form: panel.querySelector("form"),
    target: () => ({ prefix: proj().prefix || "", project: proj().id }),
    clear: () => api("DELETE", `/api/projects/${proj().id}/chat`, null, proj().prefix || ""),
    cwd: panel.querySelector(".chat-cwd"),
    // A turn left streaming when the chat was cleared is saved when it finishes.
    saved: () => { if (!pc.chat.busy) { pc.loaded = false; loadProjectChat(proj()).catch(fail); } },
    actions: chatActions(false, key),
  });
  // A project chat you talk in stays as a tab after you switch projects.
  pc.chat.input.form.addEventListener("submit", () => keepChatTab(key));
  projectChats.set(key, pc);
  return pc;
}
// The server saves every finished turn; load it once, when the chat is first shown.
async function loadProjectChat(p) {
  const pc = projectChatFor(p);
  if (pc.loaded || pc.chat.busy) return;
  pc.loaded = true;
  const saved = await api("GET", `/api/projects/${p.id}/chat`, null, p.prefix || "");
  if (!pc.chat.history.length && !pc.chat.busy) pc.chat.reset(saved);
}

// Kept project chats other than the selected project's, which is "This project".
const keptTabs = () => pane.tabs.map(projectByKey).filter((p) => p && projectKey(p) !== projectKey(state.project));
function keepChatTab(key) {
  if (pane.tabs.includes(key)) return;
  pane.tabs.push(key);
  savePane();
  renderChatPane();
}
// The tab shown: "general", "project", or a kept project chat's key.
function paneTab() {
  const t = pane.tab;
  if (t === "general") return t;
  if (t === "project" || (t && t === projectKey(state.project))) return "project";
  if (t && keptTabs().some((p) => projectKey(p) === t)) return t;
  // Unset, or a kept chat whose project is gone (or isn't loaded yet).
  return state.project ? "project" : "general";
}
const tabProject = (tab) => (tab === "general" ? null : tab === "project" ? state.project : projectByKey(tab));
// The controller of the visible tab, if it has one.
function activeChat() {
  const tab = paneTab();
  if (tab === "general") return chat;
  const p = tabProject(tab);
  return p ? projectChatFor(p).chat : null;
}

function renderChatPane() {
  const app = $(".app");
  app.classList.toggle("chat-open", pane.open);
  app.classList.toggle("chat-pinned", pane.pinned);
  app.classList.toggle("chat-overlay", !pane.pinned);
  if (pane.width) app.style.setProperty("--chat-w", `${Math.max(CHAT_MIN_W, Math.round(pane.width))}px`);
  else app.style.removeProperty("--chat-w");
  $("#chat-pane").hidden = !pane.open;
  $("#pc-open").setAttribute("aria-pressed", String(pane.open));
  const pin = $("#pc-pin");
  pin.setAttribute("aria-pressed", String(pane.pinned));
  pin.title = pane.pinned ? "Unpin the chat (overlay)" : "Pin the chat beside the content";
  pin.setAttribute("aria-label", pin.title);

  const tab = paneTab();
  const cur = tabProject(tab);
  const tabBtn = (id, label, kids, title = label) => h("button", {
    type: "button", role: "tab", class: "chat-pane-tab-btn", "aria-selected": String(tab === id), title,
    onclick: () => showChatTab(id),
  }, ...kids, h("span", { class: "chat-tab-name" }, label));
  $("#chat-tabs").replaceChildren(
    h("div", { class: "chat-pane-tab" }, tabBtn("general", "General", [ico("spark")], "General chat, in your home directory")),
    h("div", { class: "chat-pane-tab" }, tabBtn("project", "This project", [state.project ? projectIcon(state.project) : ico("repo")],
      state.project ? `${state.project.name} (follows the project picker)` : "Follows the project picker")),
    ...keptTabs().map((p) => h("div", { class: "chat-pane-tab" },
      tabBtn(projectKey(p), p.name, [projectIcon(p)], multi() ? `${p.name} · ${p.machine}` : p.name),
      ib({ type: "button", class: "icon-btn chat-tab-close", "aria-label": `Close the ${p.name} chat`, title: "Close this tab", onclick: () => {
        pane.tabs = pane.tabs.filter((k) => k !== projectKey(p));
        savePane();
        renderChatPane();
      } }, "x"))),
  );

  // Show the tab's panel; the others (and their streams) stay as they are.
  const show = (el, on) => {
    if (on && el.hidden && pane.open) requestAnimationFrame(() => { const log = el.querySelector(".chat-log"); if (log) log.scrollTop = log.scrollHeight; });
    el.hidden = !on;
  };
  show($("#chat-general"), tab === "general");
  show($("#chat-noproject"), tab === "project" && !state.project);
  if (cur && pane.open) projectChatFor(cur);
  for (const [key, pc] of projectChats) show(pc.panel, !!cur && key === projectKey(cur));
  $("#pc-clear").disabled = !activeChat();
  if (cur && pane.open) loadProjectChat(cur).catch((e) => toast(`Couldn't load the project chat: ${e.message}`, true));
}

function showChatTab(tab) {
  pane.tab = tab;
  savePane();
  renderChatPane();
  if (desktop.matches) activeChat()?.input.focus();
}
// open: true/false, or toggle. tab: the tab to show, or the last one.
function toggleChatPane(open = !pane.open, tab = null) {
  pane.open = open;
  if (tab) pane.tab = tab;
  savePane();
  renderChatPane();
  if (open) activeChat()?.input.focus();
  else if ($("#chat-pane").contains(document.activeElement)) document.activeElement.blur();
}
function togglePin() {
  pane.pinned = !pane.pinned;
  savePane();
  renderChatPane();
  if (pane.pinned && !wide.matches) toast("Pinned. The chat sits beside the content on wider windows.");
}
wide.addEventListener("change", renderChatPane);
$("#pc-open").addEventListener("click", () => toggleChatPane());
$("#pc-close").addEventListener("click", () => toggleChatPane(false));
$("#pc-pin").addEventListener("click", togglePin);
$("#pc-clear").addEventListener("click", attempt(async () => {
  const c = activeChat();
  if (c?.history.length) await c.clear();
}));

// Desktop: drag the pane's left edge to resize it, overlaid or pinned.
function setChatWidth(w, save = true) {
  pane.width = w == null ? null : Math.max(CHAT_MIN_W, Math.round(w));
  if (pane.width) $(".app").style.setProperty("--chat-w", `${pane.width}px`);
  else $(".app").style.removeProperty("--chat-w");
  if (save) savePane();
}
{
  const handle = $("#pc-resize"), panel = $("#chat-pane");
  handle.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    e.preventDefault();
    handle.setPointerCapture(e.pointerId);
    handle.classList.add("dragging");
    const right = panel.getBoundingClientRect().right;
    const move = (ev) => setChatWidth(right - ev.clientX, false);
    const up = () => {
      handle.removeEventListener("pointermove", move);
      handle.classList.remove("dragging");
      setChatWidth(panel.getBoundingClientRect().width);
    };
    handle.addEventListener("pointermove", move);
    handle.addEventListener("pointerup", up, { once: true });
    handle.addEventListener("pointercancel", up, { once: true });
  });
  handle.addEventListener("dblclick", () => setChatWidth(null));
  handle.addEventListener("keydown", (e) => {
    const step = e.shiftKey ? 64 : 16;
    const d = e.key === "ArrowLeft" ? step : e.key === "ArrowRight" ? -step : 0;
    if (!d) return;
    e.preventDefault();
    e.stopPropagation();
    setChatWidth(panel.getBoundingClientRect().width + d);
  });
}
renderChatPane();

let todoChatId = null;
async function loadTodoChat() {
  const id = state.detail;
  // Reopening the todo whose reply is still streaming keeps it on screen.
  if (todoChatId === id && todoChat.busy) return;
  todoChatId = id;
  todoChat.reset();
  const saved = await api("GET", `/api/todos/${id}/chat`);
  if (state.detail === id && !todoChat.history.length && !todoChat.busy) todoChat.reset(saved);
}

// ------------------------------------------------------------------ run: processes & terminal
const term = new window.Terminal({
  fontFamily: '"JetBrains Mono", ui-monospace, monospace', fontSize: 13, cursorBlink: true,
  theme: { background: "#0a0f17", foreground: "#e6ecf5", cursor: "#8aa4ff", selectionBackground: "#2a384d" },
});
const fit = new window.FitAddon.FitAddon();
term.loadAddon(fit);
term.open($("#term"));
let termWS = null;
let attached = null;

const sendSize = () => termWS?.readyState === 1 && termWS.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
function fitTerm() { if (state.view === "run") { try { fit.fit(); sendSize(); } catch {} } }
new ResizeObserver(fitTerm).observe($("#term"));
term.onData((data) => termWS?.readyState === 1 && termWS.send(JSON.stringify({ type: "input", data })));
// Ctrl-] leaves the terminal and returns to normal mode, like detaching in the TUI.
term.attachCustomKeyEventHandler((e) => {
  if (e.type === "keydown" && e.ctrlKey && e.key === "]") { term.blur(); setMode(); return false; }
  return true;
});

function attach(p) {
  termWS?.close();
  attached = p.id;
  term.reset();
  // Piped (non-PTY) output has bare \n with no tty driver to add the \r.
  term.options.convertEol = p.kind !== "pty";
  requestAnimationFrame(fitTerm);
  termWS = new WebSocket(wsURL(on(here(), `/ws/proc/${p.id}`)));
  termWS.binaryType = "arraybuffer";
  termWS.onopen = sendSize;
  termWS.onmessage = (m) => {
    if (typeof m.data === "string") {
      const msg = JSON.parse(m.data);
      if (msg.type === "exit") term.write(`\r\n\x1b[90mProcess exited with code ${msg.code}\x1b[0m\r\n`);
    } else {
      term.write(new Uint8Array(m.data));
    }
  };
  renderProcs();
  if (p.kind === "pty") term.focus();
}

async function startProc(req, show = true) {
  const p = await api("POST", `/api/projects/${state.project.id}/processes`, { ...req, cols: term.cols, rows: term.rows });
  if (!show) return loadProcs();
  closeDetail();
  attach(p);
  showView("run");
  if (p.url) toast(`Server starting at ${p.url}`);
}

// The Shell view is only a terminal: show the project's running shell, or open one.
let opening = false;
function ensureShell() {
  if (state.view !== "run" || !state.project || opening) return;
  if (attached && state.procs.some((p) => p.id === attached)) return;
  const pty = state.procs.filter((p) => p.kind === "pty" && p.running && p.dir === state.project.path)
    .reduce((a, b) => (!a || b.started_at > a.started_at ? b : a), null);
  if (pty) return attach(pty);
  opening = true;
  startProc({ kind: "pty" }).catch(fail).finally(() => { opening = false; });
}

const runPreset = attempt(async (e) => {
  const spec = e.target.closest("[data-run]")?.dataset.run;
  if (!spec || !state.project) return;
  const [kind, preset] = spec.split(":");
  await startProc({ kind, preset }, preset !== "deploy");
});
// While a quick action runs, clicking it shows its output instead of starting it again;
// a running server is stopped instead.
$("#quick-actions").addEventListener("click", attempt(async (e) => {
  const spec = e.target.closest("[data-run]")?.dataset.run;
  const proc = quickProc(spec);
  if (!proc?.running) return runPreset(e);
  if (spec === "web:run") {
    await api("DELETE", `/api/processes/${proc.id}`);
    toast("Stopping server");
    return loadProcs();
  }
  closeDetail();
  attach(proc);
  showView("run");
}));

// The latest server/test/deploy process started from the project's own checkout (not a worktree).
const quickCmd = (spec) => ({ "web:run": state.project?.run_command, "task:test": state.project?.test_command, "task:deploy": state.project?.deploy_command })[spec];
// What a server or deploy command runs on, read from the command itself. First match wins; a rule without a label keeps the generic one.
const TECH_RULES = {
  "web:run": [
    [/\badb\s|gradlew.*install|installDebug|run[-:]android/, "android", "Run on Android"],
    [/xcodebuild|xcrun simctl|ios-deploy|run[-:]ios/, "apple", "Run on iOS"],
    [/\bflutter run\b/, "flutter", "Run Flutter app"],
    [/\bdocker[- ](compose )?(up|run)\b/, "docker"],
    [/\bnext\b/, "nextjs"],
    [/\bvite\b/, "vitejs"],
    [/\bbunx?\b/, "bun"],
    [/\b(npm|npx|pnpm|yarn)\b/, "nodejs"],
    [/\bgo run\b/, "go"],
    [/\bcargo run\b/, "rust"],
    [/\bdotnet run\b/, "dotnetcore"],
    [/manage\.py runserver/, "django"],
  ],
  "task:deploy": [
    [/\bvercel\b/, "vercel", "Deploy to Vercel"],
    [/\bnetlify\b/, "netlify", "Deploy to Netlify"],
    [/\bfirebase deploy\b/, "firebase", "Deploy to Firebase"],
    [/\bwrangler\b/, "cloudflare", "Deploy to Cloudflare"],
    [/\bheroku\b/, "heroku", "Deploy to Heroku"],
    [/\bkubectl\b/, "kubernetes", "Deploy to Kubernetes"],
    [/\bgcloud\b/, "googlecloud", "Deploy to GCP"],
    [/\b(aws|sam|cdk)\b/, "amazonwebservices", "Deploy to AWS"],
    [/\baz\b/, "azure", "Deploy to Azure"],
    [/\bdocker[- ](compose )?(up|run)\b/, "docker"],
  ],
};
const techFor = (spec) => {
  const cmd = quickCmd(spec);
  const hit = cmd && TECH_RULES[spec]?.find(([re]) => re.test(cmd));
  return hit ? { icon: hit[1], label: hit[2] } : {};
};
const quickPlainIcons = new Map($$(".quick-btn").map((b) => [b, b.querySelector("svg")]));
function quickProc(spec) {
  const p = state.project;
  const cmd = quickCmd(spec);
  if (!cmd) return null;
  const kind = spec.split(":")[0];
  return state.procs.filter((x) => x.kind === kind && x.command === cmd && x.dir === p.path)
    .reduce((a, b) => (!a || b.started_at > a.started_at ? b : a), null);
}

function renderQuick() {
  for (const [sel, verb, generic, noun, key] of [["#quick-server", "Serving", "Start server", "server run", "R"], ["#quick-test", "Testing", "Run Tests", "test run", "T"], ["#quick-deploy", "Deploying", "Deploy", "deploy", "D"]]) {
    const btn = $(sel);
    const spec = btn.dataset.run;
    btn.hidden = !state.project;
    btn.disabled = !quickCmd(spec);
    const proc = quickProc(spec);
    const ok = proc && !proc.running && proc.exit_code === 0 && sel !== "#quick-server";
    const bad = proc && !proc.running && proc.exit_code != null && proc.exit_code !== 0;
    const cut = proc && !proc.running && proc.exit_code == null;
    const stop = !!proc?.running && sel === "#quick-server";
    btn.classList.toggle("running", !!proc?.running && !stop);
    btn.classList.toggle("stop", stop);
    btn.classList.toggle("ok", !!ok);
    btn.classList.toggle("bad", !!bad);
    const tech = techFor(spec);
    const plain = quickPlainIcons.get(btn);
    const svg = btn.querySelector("svg");
    const icon = !stop && tech.icon;
    if (icon ? svg.dataset.tech !== icon : svg !== plain) svg.replaceWith(icon ? ico(icon) : plain);
    if (sel === "#quick-server") {
      const path = plain.querySelector("path");
      path.setAttribute("d", stop ? "M7 7h10v10H7z" : "M8 5.5v13l10.5-6.5z");
      path.setAttribute("fill", stop ? "currentColor" : "none");
    }
    const done = tech.label || generic;
    const secs = proc ? Math.max(0, Math.floor((Date.now() - new Date(proc.started_at)) / 1000)) : 0;
    const elapsed = `${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, "0")}`;
    btn.querySelector("span").textContent = stop ? "Stop server" : proc?.running ? `${verb} ${elapsed}` : done;
    btn.title = btn.disabled ? `No ${noun.split(" ")[0]} command — set one in project settings`
      : stop ? "Server running — click to stop it"
      : proc?.running ? `${verb}… ${elapsed} — click to view output`
      : ok ? `Last ${noun} passed — click to run again`
      : bad ? `Last ${noun} failed (exit ${proc.exit_code}) — click to run again`
      : cut ? `Last ${noun} was interrupted by a Dash restart — click to run again`
      : `${done} (${key} on the Shell view)`;
  }
}
setInterval(() => { if ($(".quick-btn.running")) renderQuick(); }, 1000);

async function loadProcs() {
  if (!state.project) return;
  state.procs = await api("GET", `/api/projects/${state.project.id}/processes`);
  renderProcs();
}

function renderProcs() {
  renderQuick();
  const running = state.procs.filter((p) => p.running).length;
  $("#proc-badge").hidden = !running;
  $("#proc-badge").textContent = running;
  ensureShell();
}

// ------------------------------------------------------------------ activity
function addActivity(ev) {
  const d = ev.data;
  $("#activity-empty").hidden = true;
  $("#activity").prepend(h("li", {},
    h("span", { class: d.ok ? "ok" : "bad", "aria-label": d.ok ? "succeeded" : "failed" }, d.ok ? "✓" : "✗"),
    h("code", {}, d.cmd),
    h("time", {}, `${new Date(ev.time).toLocaleTimeString(timeLocale)} · ${d.ms} ms`)));
  while ($("#activity").children.length > 300) $("#activity").lastChild.remove();
}

// ------------------------------------------------------------------ history
// The default branch's commit graph, as `git log --graph` draws it.
async function loadGraph() {
  const p = state.project;
  if (!p) return renderGraph(null);
  const res = await api("GET", `/api/projects/${p.id}/graph`);
  if (state.project === p) renderGraph(res);
}

let graphTimer = 0;
const refreshGraph = () => { clearTimeout(graphTimer); graphTimer = setTimeout(() => state.view === "history" && loadGraph().catch(() => {}), 800); };

function renderGraph(res) {
  const lines = res?.graph ? res.graph.split("\n") : [];
  $("#graph-empty").hidden = lines.length > 0;
  $("#graph-empty-text").textContent = state.project ? `${state.project.default_branch || "main"} has no commits yet.` : "Select a project to see its main branch.";
  // Commits above origin's tip haven't been pushed yet; dim them so the last push stands out.
  const remote = `origin/${res?.branch || state.project?.default_branch || "main"}`;
  const isRemote = (line) => line.split("\x1f")[2]?.split(", ").includes(remote);
  let unpushed = lines.some(isRemote);
  $("#graph").replaceChildren(...lines.map((line) => {
    const i = line.indexOf("\x1f");
    const cls = unpushed ? " graph-unpushed" : "";
    if (i < 0) return h("li", { class: "graph-edge" + cls }, h("span", { class: "graph-lines" }, line));
    const [sha, refs, subject, author, when] = line.slice(i + 1).split("\x1f");
    const pushed = unpushed && isRemote(line);
    if (pushed) unpushed = false;
    const ref = (r) => r === remote
      ? h("span", { class: "graph-ref remote", title: "Last pushed commit" }, `pushed · ${r}`)
      : h("span", { class: `graph-ref${r.startsWith("tag: ") ? " tag" : ""}` }, r.replace(/^HEAD -> /, ""));
    return h("li", { class: pushed ? "graph-pushed" : cls.trim(), title: cls ? "Not pushed yet" : null },
      h("span", { class: "graph-lines" }, line.slice(0, i)),
      h("span", { class: "graph-commit" },
        h("code", { class: "graph-sha" }, sha),
        ...(refs ? refs.split(", ").map(ref) : []),
        h("span", { class: "graph-subject" }, subject),
        h("span", { class: "graph-meta" }, `${author} · ${when}`)));
  }));
}

// ------------------------------------------------------------------ files
// The default branch's files as a tree, and a plain text editor. Saving
// doesn't write to the branch: it queues a task that commits the edit in its
// own worktree and goes to review. Each project keeps its open file, so
// switching projects loses nothing.
const fileSessions = new Map(); // project key → { list, tree, open, path, blob, original, text, note, size, saved }
const fileText = $("#file-text");
function fileSession() {
  if (!state.project) return null;
  const k = projectKey(state.project);
  if (!fileSessions.has(k)) fileSessions.set(k, { list: null, tree: null, open: new Set(), path: null });
  return fileSessions.get(k);
}
const fileDirty = (s) => !!s?.path && !s.note && s.text !== s.original;

async function loadFiles() {
  const s = fileSession(), p = state.project;
  renderFileTree();
  renderFile();
  if (!s) return;
  const res = await api("GET", `/api/projects/${p.id}/files`);
  s.list = res.files;
  s.tree = null;
  if (fileSession() === s) renderFileTree();
}

function fileTreeOf(s) {
  if (s.tree) return s.tree;
  const node = () => ({ dirs: new Map(), files: [] });
  s.tree = node();
  for (const f of s.list) {
    const parts = f.split("/");
    let n = s.tree;
    for (const d of parts.slice(0, -1)) {
      if (!n.dirs.has(d)) n.dirs.set(d, node());
      n = n.dirs.get(d);
    }
    n.files.push(parts.at(-1));
  }
  return s.tree;
}

const fileItem = (s, path, label) => h("button", {
  type: "button", class: "file-item", title: path, "aria-current": s.path === path ? "true" : null,
  onclick: () => openFile(path).catch(fail),
}, label);

// Folders render their contents when first opened, so big repositories stay quick.
function dirNodes(s, node, prefix) {
  const dirs = [...node.dirs.keys()].sort().map((name) => {
    const path = prefix + name, sub = node.dirs.get(name);
    const d = h("details", { class: "file-dir", open: s.open.has(path) }, h("summary", { title: path }, name));
    const fill = () => { if (d.childElementCount === 1) d.append(h("div", { class: "file-kids" }, ...dirNodes(s, sub, path + "/"))); };
    if (d.open) fill();
    d.addEventListener("toggle", () => { if (d.open) { s.open.add(path); fill(); } else s.open.delete(path); });
    return d;
  });
  return [...dirs, ...[...node.files].sort().map((name) => fileItem(s, prefix + name, name))];
}

function renderFileTree() {
  const s = fileSession(), tree = $("#file-tree");
  const note = (text) => h("p", { class: "file-note" }, text);
  if (!s) return tree.replaceChildren(note("Select a project to browse its files."));
  if (!s.list) return tree.replaceChildren(note("Loading…"));
  if (!s.list.length) return tree.replaceChildren(note("No files on the default branch yet."));
  const q = $("#file-filter").value.trim().toLowerCase();
  if (!q) return tree.replaceChildren(...dirNodes(s, fileTreeOf(s), ""));
  const hits = s.list.filter((f) => f.toLowerCase().includes(q)), max = 300;
  tree.replaceChildren(...hits.slice(0, max).map((f) => fileItem(s, f, f)),
    hits.length > max ? note(`${hits.length - max} more; type more to narrow it down`) : null,
    hits.length ? null : note("No matching files"));
}

function renderFile() {
  const s = fileSession(), editable = !!s?.path && !s.note, dirty = fileDirty(s);
  $("#file-head").hidden = !s?.path;
  fileText.hidden = !editable;
  $("#file-empty").hidden = editable;
  if (s?.path) $("#file-path").textContent = s.path;
  if (editable && fileText.value !== s.text) { fileText.value = s.text; fileText.scrollTop = 0; }
  $("#file-save").disabled = $("#file-revert").disabled = !dirty;
  $("#file-state").textContent = dirty ? "Modified" : editable && s.saved ? "Saved as a task" : "";
  $("#file-empty-title").textContent = s?.note === "binary" ? "Binary file" : s?.note === "large" ? "File too large" : "No file open";
  $("#file-empty-text").textContent = s?.note === "binary" ? `${s.path} isn't text, so it can't be edited here.`
    : s?.note === "large" ? `${s.path} is ${Math.round(s.size / 1024)} KiB; the editor opens files up to 512 KiB.`
    : s ? "Pick a file on the left to view and edit it. Saving creates a task that goes to review like any other."
    : "Select a project to browse its files.";
}

async function openFile(path) {
  const s = fileSession(), p = state.project;
  if (!s || s.path === path) return;
  if (fileDirty(s) && !(await ask({ title: `Discard your changes to ${s.path}?`, ok: "Discard", danger: true }))) return;
  const res = await api("GET", `/api/projects/${p.id}/file?path=${encodeURIComponent(path)}`, null, p.prefix || "");
  const text = res.content ?? "";
  Object.assign(s, { path, blob: res.blob, original: text, text, size: res.size, saved: false,
    note: res.binary ? "binary" : res.too_large ? "large" : "" });
  if (fileSession() !== s) return;
  renderFile();
  renderFileTree();
}

async function saveFile() {
  const s = fileSession(), p = state.project;
  if (!fileDirty(s)) return;
  const { path, blob, text } = s;
  const title = await ask({
    title: "Save as a task", input: true, placeholder: `Edit ${path}`, ok: "Save as task",
    body: `The edit to ${path} is committed in its own worktree and goes to review like any other task. Name it, or leave it blank.`,
  });
  if (title == null) return;
  const t = await api("POST", `/api/projects/${p.id}/edits`, { path, blob, content: text, title }, p.prefix || "");
  if (s.path === path) { s.original = text; s.saved = true; }
  if (fileSession() === s) renderFile();
  toast(`Saved as task “${t.title}”`);
}

fileText.addEventListener("input", () => {
  const s = fileSession();
  if (!s) return;
  const was = fileDirty(s);
  s.text = fileText.value;
  if (was !== fileDirty(s)) renderFile();
});
fileText.addEventListener("keydown", (e) => {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") { e.preventDefault(); saveFile().catch(fail); return; }
  if (e.key === "Escape") { fileText.blur(); return; }
  // Tab indents; Escape first to move focus on with Tab.
  if (e.key === "Tab" && !e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey) {
    e.preventDefault();
    if (!document.execCommand("insertText", false, "\t")) fileText.setRangeText("\t", fileText.selectionStart, fileText.selectionEnd, "end");
  }
});
$("#file-save").addEventListener("click", () => saveFile().catch(fail));
$("#file-revert").addEventListener("click", () => {
  const s = fileSession();
  if (!s) return;
  s.text = s.original;
  renderFile();
});
$("#file-filter").addEventListener("input", renderFileTree);
addEventListener("beforeunload", (e) => { if ([...fileSessions.values()].some(fileDirty)) e.preventDefault(); });

// ------------------------------------------------------------------ drag & drop
// Drag a card to another lane to act on it, or within a lane to reorder.
// Mouse: drag after a few pixels. Touch: long-press, then drag (a quick
// swipe still scrolls). Lane tabs are drop targets on phones.
const drag = { active: false, pending: null, t: null, card: null, ghost: null, slot: null, target: null, dx: 0, dy: 0, suppressClick: false };

// What dropping a todo of a status into a lane does (null = not allowed).
function dropAction(t, lane) {
  const from = t.status;
  const to = LANES.find((l) => l.key === lane);
  if (!to) return null;
  if (to.statuses.includes(from)) return ["draft", "queued", "review"].includes(lane) ? { kind: "reorder" } : null;
  if (t.reviewing) return null; // locked until the review finishes
  const go = (verb, label) => ({ kind: "action", verb, label });
  if (lane === "queued" && ["draft", "failed"].includes(from)) return go("enqueue", "Added to queue");
  if (lane === "queued" && from === "review") return { kind: "rework" };
  if (lane === "draft" && ["queued", "review", "failed"].includes(from)) return go("cancel", "Moved to drafts");
  if (lane === "merging" && from === "review") return go("approve", "Approved — merging");
  return null;
}

$("#board").addEventListener("pointerdown", (e) => {
  const card = e.target.closest(".todo[data-id]");
  if (!card || e.button > 0) return;
  const t = state.todos.get(card.dataset.id);
  if (!t) return;
  drag.pending = { card, t, x: e.clientX, y: e.clientY, touch: e.pointerType !== "mouse" };
  if (drag.pending.touch) {
    drag.pending.timer = setTimeout(() => drag.pending && startDrag(drag.pending.x, drag.pending.y), 320);
  }
});

document.addEventListener("pointermove", (e) => {
  if (drag.active) { moveDrag(e.clientX, e.clientY); return; }
  const p = drag.pending;
  if (!p) return;
  const dist = Math.hypot(e.clientX - p.x, e.clientY - p.y);
  if (p.touch) { if (dist > 10) cancelPending(); return; } // it's a scroll
  if (dist > 6) startDrag(e.clientX, e.clientY);
});
// While dragging on touch, stop the page from scrolling under the finger.
document.addEventListener("touchmove", (e) => { if (drag.active) e.preventDefault(); }, { passive: false });
document.addEventListener("pointerup", (e) => { if (drag.active) endDrag(e.clientX, e.clientY); cancelPending(); });
document.addEventListener("pointercancel", () => { if (drag.active) abortDrag(); cancelPending(); });
document.addEventListener("keydown", (e) => { if (drag.active && e.key === "Escape") { e.stopPropagation(); abortDrag(); } }, true);
// A drag ends with a click on the card; swallow it so the detail doesn't open.
document.addEventListener("click", (e) => { if (drag.suppressClick) { e.stopPropagation(); e.preventDefault(); drag.suppressClick = false; } }, true);
$("#board").addEventListener("contextmenu", (e) => { if (e.target.closest(".todo")) e.preventDefault(); });

function cancelPending() {
  if (drag.pending?.timer) clearTimeout(drag.pending.timer);
  drag.pending = null;
}

function startDrag(x, y) {
  const { card, t } = drag.pending;
  cancelPending();
  const r = card.getBoundingClientRect();
  drag.active = true;
  drag.t = t;
  drag.card = card;
  drag.dx = x - r.left;
  drag.dy = y - r.top;
  drag.ghost = card.cloneNode(true);
  drag.ghost.classList.add("drag-ghost");
  drag.ghost.style.width = `${r.width}px`;
  document.body.append(drag.ghost);
  drag.slot = h("li", { class: "drop-slot", "aria-hidden": "true" });
  drag.slot.style.height = `${r.height}px`;
  card.classList.add("dragging");
  document.body.classList.add("is-dragging");
  navigator.vibrate?.(12);
  markTargets();
  showDropBar();
  moveDrag(x, y);
}

// On phones the other lanes are off-screen, so a drag shows a bar of large
// drop targets for exactly the moves this card allows.
const DROP_LABEL = { enqueue: "Add to queue", cancel: "Back to drafts", approve: "Approve and merge" };
function showDropBar() {
  if (desktop.matches) return;
  const zones = LANES.map((l) => [l, dropAction(drag.t, l.key)])
    .filter(([l, a]) => a && a.kind !== "reorder")
    .map(([l, a]) => h("div", { class: `drop-zone s-${l.key === "done" ? "merged" : l.key}`, "data-lane": l.key },
      a.kind === "rework" ? "Send back for rework" : DROP_LABEL[a.verb] || l.label));
  const bar = h("div", { class: "drop-bar", id: "drop-bar" },
    zones.length ? zones : h("div", { class: "drop-zone none" }, "Drag up or down to reorder"));
  document.body.append(bar);
}

// Highlight lanes (columns and mobile tabs) where this card may be dropped.
function markTargets() {
  for (const el of $$(".col[data-lane], .lane-tab[data-lane]")) {
    const ok = !!dropAction(drag.t, el.dataset.lane);
    el.classList.toggle("drop-ok", ok);
    el.classList.toggle("drop-no", !ok);
  }
}

function moveDrag(x, y) {
  drag.ghost.style.transform = `translate(${x - drag.dx}px, ${y - drag.dy}px) rotate(1.2deg) scale(1.02)`;
  const under = document.elementFromPoint(x, y);
  const laneEl = under?.closest(".drop-zone[data-lane], .col[data-lane], .lane-tab[data-lane]");
  const lane = laneEl?.dataset.lane || null;
  const action = lane ? dropAction(drag.t, lane) : null;
  $$(".drop-over").forEach((el) => el !== laneEl && el.classList.remove("drop-over"));
  drag.target = action ? { lane, action, index: Infinity } : null;
  if (!action) { drag.slot.remove(); return; }
  laneEl.classList.add("drop-over");

  // Inside a visible column, show where the card would land.
  const col = laneEl.classList.contains("col") ? laneEl : null;
  const rail = col?.querySelector(".rail") || null;
  if (!col || laneEl.matches(".col:not(.active)") && !desktop.matches) { drag.slot.remove(); return; }
  const cards = [...col.querySelectorAll(".todo[data-id]")].filter((c) => c !== drag.card);
  let index = cards.findIndex((c) => { const r = c.getBoundingClientRect(); return y < r.top + r.height / 2; });
  if (index < 0) index = cards.length;
  drag.target.index = index;
  if (rail) {
    const ref = cards[index]?.closest("li") || null;
    if (drag.slot.nextSibling !== ref || drag.slot.parentNode !== rail) rail.insertBefore(drag.slot, ref);
  } else {
    col.querySelector(".col-body")?.prepend(drag.slot);
  }
  autoScroll(col.querySelector(".col-body") || document.scrollingElement, y);
}

function autoScroll(el, y) {
  const r = el === document.scrollingElement ? { top: 0, bottom: innerHeight } : el.getBoundingClientRect();
  if (y < r.top + 60) el.scrollBy({ top: -14 });
  else if (y > r.bottom - 60) el.scrollBy({ top: 14 });
}

function cleanupDrag() {
  drag.ghost?.remove();
  drag.slot?.remove();
  const bar = $("#drop-bar");
  if (bar) leave(bar, "leaving", () => bar.remove(), 160);
  drag.card?.classList.remove("dragging");
  document.body.classList.remove("is-dragging");
  $$(".drop-ok, .drop-no, .drop-over").forEach((el) => el.classList.remove("drop-ok", "drop-no", "drop-over"));
  drag.active = false;
  drag.suppressClick = true;
  setTimeout(() => { drag.suppressClick = false; }, 0);
}

function abortDrag() {
  // Fly the ghost back to where the card was.
  const g = drag.ghost, home = drag.card.getBoundingClientRect();
  if (g && !reduceMotion.matches) {
    g.animate([{ transform: g.style.transform }, { transform: `translate(${home.left}px, ${home.top}px)` }], { duration: 200, easing: EASE });
    setTimeout(() => { cleanupDrag(); renderBoard(); }, 190);
  } else { cleanupDrag(); renderBoard(); }
}

async function endDrag() {
  const target = drag.target, t = drag.t;
  if (!target) return abortDrag();
  cleanupDrag();
  try {
    if (target.action.kind === "reorder") {
      await reorder(t, target.lane, target.index);
    } else if (target.action.kind === "rework") {
      renderBoard();
      const feedback = await ask({ title: "Send back for rework", body: "Claude continues in the same worktree with your notes.", input: true, placeholder: "What should change?", ok: "Send back" });
      if (feedback === null) return;
      await api("POST", `/api/todos/${t.id}/rework`, { feedback });
      toast("Sent back for rework");
    } else {
      // Optimistic: show it in the new lane right away; the server event confirms.
      const lane = LANES.find((l) => l.key === target.lane);
      state.todos.set(t.id, { ...t, status: lane.statuses[0] });
      renderBoard();
      await api("POST", `/api/todos/${t.id}/${target.action.verb}`);
      toast(target.action.label);
      if (target.lane === "queued" && Number.isFinite(target.index)) await reorder(state.todos.get(t.id), "queued", target.index);
    }
  } catch (err) {
    state.todos.set(t.id, t); // undo the optimistic move
    renderBoard();
    fail(err);
  }
}

// Reorder a lane by rewriting priorities 0..n-1 (lower runs first).
async function reorder(t, laneKey, index) {
  const lane = laneItems()[laneKey].filter((x) => x.id !== t.id);
  lane.splice(Math.min(index, lane.length), 0, t);
  const changes = lane.map((x, i) => [x, i]).filter(([x, i]) => x.priority !== i);
  for (const [x, i] of changes) state.todos.set(x.id, { ...state.todos.get(x.id), priority: i });
  renderBoard();
  await Promise.all(changes.map(([x, i]) => api("PATCH", `/api/todos/${x.id}`, { priority: i })));
}

// ------------------------------------------------------------------ vim keys
// Normal mode is the default; typing in a field or the terminal is insert
// mode. Esc (Ctrl-] in the terminal) returns to normal mode.
const VIEWS = ["board", "run", "activity", "history", "files"];
const keys = { active: false, count: 0, pending: "", cur: { lane: 0, row: 0 } };

const BOUND = /^(:|\?|gt|gT|gg|gx|gb|gc|gs|ga|gh|gf|G|u|p|\[|q|Escape|y|Y|A|n|N|j|k|h|l|w|b|o|O|s|x|a|r|e|E|\+|-|K|J|\*|t|T|!|dd|i|I|R|D|\/|Enter| |Arrow(Up|Down|Left|Right)|ctrl\+[dufb])$/;
const isTyping = (el) => el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName) || el.closest?.(".xterm"));
const openDialog = () => document.querySelector("dialog[open]");

function setMode() {
  const el = $("#kbd-status");
  const typing = isTyping(document.activeElement);
  const mode = document.activeElement?.id === "cmd-input" ? "command" : typing ? "insert" : "normal";
  el.dataset.mode = mode;
  el.textContent = mode.toUpperCase() +(keys.count || keys.pending ? `  ${keys.count || ""}${keys.pending}` : "");
}
document.addEventListener("focusin", setMode);
document.addEventListener("focusout", () => setTimeout(setMode));
// Mouse or touch hides the keyboard cursor; a key brings it back.
document.addEventListener("pointerdown", () => { if (keys.active) { keys.active = false; renderBoard(); } });

function laneCount() { return LANES.length; }
function laneTodos(li) { return laneItems()[LANES[li].key] || []; }
function cursorTodo() { return laneTodos(keys.cur.lane)[keys.cur.row] || null; }
// Minimized lanes (desktop only) and hidden ones are skipped by lane navigation.
function laneSkipped(li) { return (desktop.matches && state.collapsed.has(LANES[li].key)) || laneHidden(LANES[li].key); }
// With auto approve, finished work skips Review; the lane only shows while
// something still waits there (failing tests, a merge that came back).
function laneHidden(key) {
  return key === "review" && !!state.project?.auto_approve && ![...state.todos.values()].some((t) => t.status === "review");
}
function stepLane(lane, d) {
  const step = Math.sign(d);
  for (let li = lane + step, left = Math.abs(d); li >= 0 && li < laneCount(); li += step) {
    if (!laneSkipped(li)) { lane = li; if (!--left) break; }
  }
  return lane;
}

function moveCursor(lane, row) {
  lane = Math.max(0, Math.min(laneCount() - 1, lane));
  const n = laneTodos(lane).length;
  keys.cur = { lane, row: Math.max(0, Math.min(n - 1, row)) };
  keys.active = true;
  if (!desktop.matches) state.lane = LANES[lane].key; // mobile shows one lane
  renderBoard();
  ($(".todo.cursor") || $(".col.cursor"))?.scrollIntoView({ block: "nearest", inline: "nearest" });
}

// The element j/k and Ctrl-d/u scroll in the current context.
function scroller() {
  if (state.detail) return $(".detail-body");
  return desktop.matches ? $(".view.active") : document.scrollingElement;
}

function scrollBy(el, how, n) {
  const page = el.clientHeight || innerHeight;
  const delta = { j: 48, k: -48, "ctrl+d": page / 2, "ctrl+u": -page / 2, "ctrl+f": page * 0.9, "ctrl+b": -page * 0.9 }[how];
  if (how === "gg") el.scrollTo({ top: 0 });
  else if (how === "G") el.scrollTo({ top: el.scrollHeight });
  else el.scrollBy({ top: delta * n });
}

// What Enter does to a task: approve one in review, enqueue a draft.
function enterKey(t) { return { review: "a", draft: "s" }[t.status]; }

// Actions on a todo; shared by the board cursor and the open detail view.
async function todoKey(t, k) {
  const post = (verb, body, msg) => api("POST", `/api/todos/${t.id}/${verb}`, body).then(() => toast(msg));
  switch (k) {
    case "s": return post("enqueue", null, "Added to queue");
    case "x": return post("cancel", null, t.status === "in_progress" ? "Stopping" : "Moved to drafts");
    case "z": return t.paused ? post("resume", null, "Resumed") : post("pause", null, t.status === "in_progress" ? "Pausing" : "Paused");
    case "a": return post("approve", null, "Approved — merging");
    case "r": return reworkTodo(t);
    case "u": return revertTodo(t);
    case "gx":
      if (!t.pr) throw new Error("This task has no pull request.");
      return window.open(t.pr.url, "_blank", "noopener");
    case "e": return openTodoForm(t);
    case "+": case "K": return api("PATCH", `/api/todos/${t.id}`, { priority: t.priority - 1 });
    case "-": case "J": return api("PATCH", `/api/todos/${t.id}`, { priority: t.priority + 1 });
    case "*": return api("PATCH", `/api/todos/${t.id}`, { goal: !t.goal });
    case "t": return startProc({ kind: "web", preset: "run", todo_id: t.id });
    case "!": return startProc({ kind: "pty", todo_id: t.id });
    case "dd":
      if (await ask({ title: `Delete "${title(t)}"?`, body: "Its worktree and branch are removed too. This can't be undone.", ok: "Delete", danger: true })) {
        await api("DELETE", `/api/todos/${t.id}`);
        if (state.detail === t.id) closeDetail();
        toast("Task deleted");
      }
      return;
  }
  if (k === "T") return api("POST", `/api/todos/${t.id}/test`).then(() => toast("Running tests…"));
  if (k === "Y") return api("POST", `/api/todos/${t.id}/duplicate`).then(() => toast("Duplicated as a draft"));
  if (k === "E") return api("POST", `/api/todos/${t.id}/open`).then(() => toast("Opening in your editor"));
  return false; // not a todo key
}

// y / A / n answer the permission request in view: the open todo's, else the oldest.
async function permKey(k) {
  const p = state.perms.find((x) => x.todo_id === state.detail) || (!state.detail && state.perms[0]);
  if (!p) return false;
  const decision = { y: "allow", A: "always", n: "deny" }[k];
  await api("POST", `/api/permissions/${p.id}`, { decision });
  toast(decision === "deny" ? "Denied" : decision === "always" ? `${p.tool} always allowed in this project` : "Allowed");
}

async function runCommand(line) {
  line = line.trim().replace(/^:/, "");
  if (!line) return;
  if (/^\d+$/.test(line)) { moveCursor(keys.cur.lane, Number(line) - 1); return; }
  const [name, ...rest] = line.split(/\s+/);
  const arg = rest.join(" ");
  const need = () => { if (!state.project) throw new Error("Select a project first (p)."); return state.project; };
  switch (name) {
    case "q": case "q!": case "close": closeDetail(); openDialog()?.close(); return;
    case "b": case "board": return showView("board");
    case "c": case "chat": return toggleChatPane();
    case "pin": case "unpin": return togglePin();
    case "run": case "!": case "sh": case "shell":
      if (!arg) return showView("run");
      need(); return startProc({ kind: "pty", command: arg });
    case "ps": case "procs": return showView("run");
    case "activity": case "log": return showView("activity");
    case "history": case "graph": case "tree": return showView("history");
    case "p": case "project": {
      if (!arg) return openProjects();
      const [pn, mn = ""] = arg.toLowerCase().split("@");
      const p = state.projects.find((x) => x.name.toLowerCase().startsWith(pn) && x.machine.toLowerCase().startsWith(mn));
      if (!p) throw new Error(`No project matching "${arg}".`);
      return selectProject(p);
    }
    case "np": case "newproject": {
      const [pname, path = ""] = arg.split(/\s+/, 2);
      if (!pname) throw new Error("Usage: :newproject <name> [path]");
      const p = await api("POST", "/api/projects", { name: pname, path });
      const machine = state.project?.machine || state.machines?.[0]?.name;
      await loadProjects();
      await selectProject(state.projects.find((x) => x.id === p.id && x.machine === machine));
      return toast(`Created ${p.name}`);
    }
    case "new": case "o":
      need(); openTodoForm(); if (arg) $("#todo-form").prompt.value = arg; return;
    case "todo": case "task":
      if (!arg) throw new Error("Usage: :task <instructions>");
      await api("POST", `/api/projects/${need().id}/todos`, { prompt: arg, enqueue: true });
      return toast("Added to queue");
    case "cleanup": case "clean": need(); return cleanup();
    case "ci": case "builds": return openCI();
    case "push": need(); return pushDone();
    case "pause": case "resume":
      state.usage = await api("POST", `/api/queue/${name}`);
      renderUsage();
      return toast(name === "pause" ? "Queue paused" : "Queue resumed");
    case "usage": renderUsage(); return $("#usage-sheet").showModal();
    case "settings": need(); return openSettings();
    case "perms": case "permissions":
      if (!state.perms.length) return toast("No permission requests waiting");
      showView("board"); closeDetail();
      return $("#perm-banner").scrollIntoView({ block: "nearest" });
    case "noh": case "nohlsearch": return clearSearch();
    case "notify": case "notifications": return toggleNotifications();
    case "clear": {
      const c = activeChat();
      if (!c) throw new Error("Pick a project first.");
      return c.clear();
    }
    case "help": case "h": return $("#keys-sheet").showModal();
    case "logout": return logout();
    case "e": case "e!": case "refresh": return loadProjects();
  }
  throw new Error(`Not a command: ${name}. Press ? for help.`);
}

function openCommandLine() {
  const input = $("#cmd-input");
  input.value = "";
  input.focus();
}
$("#cmd-input").addEventListener("blur", (e) => { e.target.value = ""; });
$("#cmd-form").addEventListener("submit", (e) => {
  e.preventDefault();
  const line = $("#cmd-input").value;
  $("#cmd-input").blur();
  attempt(runCommand)(line);
});

// ------------------------------------------------------------------ palette
// Ctrl-k: one search over commands, projects and the current project's todos.
// A leading > limits it to commands, @ to projects, # to todos.
const palette = { items: [], sel: 0 };

// Every word must appear in the text, as a substring (best) or in order.
function fuzzyScore(text, q) {
  text = text.toLowerCase();
  let total = 0;
  for (const w of q.toLowerCase().split(/\s+/).filter(Boolean)) {
    const i = text.indexOf(w);
    if (i >= 0) { total += 100 - Math.min(i, 50) + (i === 0 || /\W/.test(text[i - 1]) ? 40 : 0); continue; }
    let from = 0, prev = -2, s = 0;
    for (const c of w) {
      const j = text.indexOf(c, from);
      if (j < 0) return -1;
      s += j === prev + 1 ? 3 : 1;
      prev = j; from = j + 1;
    }
    total += s;
  }
  return total;
}

function paletteCommands() {
  const p = state.project;
  const go = (view) => () => { closeDetail(); showView(view); };
  const serve = techFor("web:run"), deploy = techFor("task:deploy");
  return [
    p && ["New task", "plus", () => openTodoForm(), "a", "add create todo"],
    ["Board", "flag", go("board"), "gb", "view lanes"],
    ["Toggle chat", "comment", () => toggleChatPane(), "gc", "chat open close claude ask project general"],
    [pane.pinned ? "Unpin chat" : "Pin chat", "pin", togglePin, ":pin", "pin unpin chat overlay dock"],
    ["Shell", "terminal", go("run"), "gs", "run terminal processes view"],
    ["Activity", "log", go("activity"), "ga", "events view"],
    ["History", "log", go("history"), "gh", "git graph tree commits view"],
    ["Files", "code", go("files"), "gf", "browse edit source code tree editor"],
    p && ["Filter the board", "search", openSearch, "/", "search todos tasks"],
    ["Switch project", "repo", openProjects, "p", "projects"],
    ["New project", "plus", openNewProject, "", "create add"],
    p && ["Project settings", "settings", openSettings, ":settings", "configure commands"],
    p?.run_command && [serve.label || "Start server", serve.icon || "play", () => startProc({ kind: "web", preset: "run" }), "R", `run web ${serve.icon || ""}`],
    p?.test_command && ["Run tests", "check", () => startProc({ kind: "task", preset: "test" }), "T", "test"],
    p?.deploy_command && [deploy.label || "Deploy", deploy.icon || "rocket", () => startProc({ kind: "task", preset: "deploy" }), "D", `release ship ${deploy.icon || ""}`],
    p && ["Open a shell", "terminal", () => startProc({ kind: "pty" }), "!", "terminal pty"],
    p && state.unpushed > 0 && ["Push merged work", "push", pushDone, ":push", "git"],
    p && ["Clean up", "trash", cleanup, ":cleanup", "worktrees branches"],
    p && !p.remote_url && ["Create GitHub repo", "repo", createGitHubRepo, "", "github remote"],
    ["Builds", "checks", openCI, ":ci", "ci github actions"],
    ["Claude usage", "clock", () => { renderUsage(); $("#usage-sheet").showModal(); }, ":usage", "limits"],
    state.usage && [state.usage.paused ? "Resume the queue" : "Pause the queue", state.usage.paused ? "play" : "pause", () => runCommand(state.usage.paused ? "resume" : "pause"), "", "queue"],
    ["Permission requests", "eye", () => runCommand("perms"), ":perms", "approvals allow deny"],
    [notifyLabel(), notifyOn() ? "bell-off" : "bell", toggleNotifications, ":notify", "notifications"],
    desktop.matches && [sideCollapsed() ? "Expand sidebar" : "Collapse sidebar", "minimize", () => setSideCollapsed(!sideCollapsed()), "[", "sidebar"],
    ["Refresh projects", "redo", loadProjects, ":refresh", "reload"],
    ["Keyboard shortcuts", "code", () => $("#keys-sheet").showModal(), "?", "help keys"],
    ["Log out", "logout", logout, "", "sign out"],
  ].filter(Boolean).map(([label, icon, run, keys, words]) => ({ kind: "Command", label, icon, run, keys, text: `${label} ${words}` }));
}

function paletteProjects() {
  return state.projects.filter((p) => projectKey(p) !== projectKey(state.project)).map((p) => ({
    kind: "Project", label: p.name, icon: "repo", hint: multi() ? p.machine : p.default_branch,
    text: `${p.name} ${p.machine} ${p.path}`, run: () => selectProject(p),
  }));
}

// Every todo, lane by lane, regardless of the board's filter or hidden old ones.
function paletteTodos() {
  const all = [...state.todos.values()];
  return LANES.flatMap((l) => all.filter((t) => l.statuses.includes(t.status)).sort(byPriority).map((t) => ({
    kind: "Task", label: title(t), icon: "draft", hint: t.paused ? "Paused" : STATUS_LABEL[t.status] || t.status,
    text: `${title(t)} ${t.prompt} ${t.id} ${STATUS_LABEL[t.status] || ""}`, run: () => { showView("board"); return openDetail(t.id); },
  })));
}

function paletteResults(raw) {
  const mode = { ">": "Command", "@": "Project", "#": "Task" }[raw[0]];
  const q = (mode ? raw.slice(1) : raw).trim();
  const sources = { Command: paletteCommands, Project: paletteProjects, Task: () => (state.project ? paletteTodos() : []) };
  const pools = (mode ? [mode] : ["Command", "Project", "Task"]).map((k) => sources[k]());
  let out;
  if (!q) out = pools.flatMap((p) => p.slice(0, mode ? 200 : 8));
  else {
    out = pools.flat().map((it) => {
      const s = fuzzyScore(it.label, q);
      return { it, s: s >= 0 ? s * 2 : fuzzyScore(it.text, q) };
    }).filter((x) => x.s >= 0).sort((a, b) => b.s - a.s).slice(0, 60).map((x) => x.it);
  }
  if (q && !mode && state.project) {
    out.push(
      { kind: "Action", label: `New task: ${q}`, icon: "plus", run: () => { openTodoForm(); $("#todo-form").prompt.value = q; promptEditor.render(); draft.changed(); } },
      { kind: "Action", label: `Ask the project chat: ${q}`, icon: "comment", run: () => { const c = projectChatFor(state.project).chat; askChat(c.input, c.input.form, q, () => toggleChatPane(true, "project")); } },
    );
  }
  if (q && !mode) out.push({ kind: "Action", label: `Ask Claude: ${q}`, icon: "spark", run: () => askChat(chat.input, $("#chat-form"), q, () => toggleChatPane(true, "general")) });
  return out;
}

function askChat(input, form, q, show) {
  show();
  input.value = q;
  input.dispatchEvent(new Event("input"));
  form.requestSubmit();
}

function renderPalette() {
  const list = $("#palette-list");
  const input = $("#palette-input");
  palette.sel = Math.max(0, Math.min(palette.items.length - 1, palette.sel));
  let group = null;
  const rows = [];
  palette.items.forEach((it, i) => {
    if (!input.value.trim() && it.kind !== group) rows.push(h("li", { class: "palette-group", role: "presentation" }, `${it.kind}s`));
    group = it.kind;
    rows.push(h("li", {
      id: `palette-${i}`, role: "option", class: "palette-item", "aria-selected": String(i === palette.sel),
      onmousemove: () => { if (palette.sel !== i) { palette.sel = i; renderPalette(); } },
      onclick: () => runPalette(i),
    }, ico(it.icon), h("span", { class: "palette-label" }, it.label),
    it.hint ? h("span", { class: "palette-hint" }, it.hint) : null,
    it.keys ? h("kbd", {}, it.keys) : input.value.trim() ? h("span", { class: "palette-kind" }, it.kind) : null));
  });
  list.replaceChildren(...(rows.length ? rows : [h("li", { class: "palette-empty", role: "presentation" }, "No matches")]));
  if (palette.items.length) input.setAttribute("aria-activedescendant", `palette-${palette.sel}`);
  else input.removeAttribute("aria-activedescendant");
  $(`#palette-${palette.sel}`)?.scrollIntoView({ block: "nearest" });
}

function updatePalette() {
  palette.items = paletteResults($("#palette-input").value);
  palette.sel = 0;
  renderPalette();
}

function openPalette(prefill = "") {
  setPicker(false);
  setMenu(false);
  const input = $("#palette-input");
  input.value = prefill;
  updatePalette();
  $("#palette").showModal();
  input.focus();
}

function runPalette(i) {
  const it = palette.items[i];
  if (!it) return;
  $("#palette").close();
  attempt(it.run)();
}

$("#palette-input").addEventListener("input", updatePalette);
$("#palette-input").addEventListener("keydown", (e) => {
  const step = { ArrowDown: 1, ArrowUp: -1 }[e.key] ?? (e.ctrlKey && { n: 1, p: -1 }[e.key]);
  const page = { PageDown: 8, PageUp: -8 }[e.key];
  if (step || page) {
    const n = palette.items.length;
    if (n) palette.sel = page ? palette.sel + page : (palette.sel + step + n) % n;
    renderPalette();
  } else if (e.key === "Enter" && !e.isComposing) runPalette(palette.sel);
  else return;
  e.preventDefault();
});
$("#palette").addEventListener("click", (e) => { if (e.target.id === "palette") e.target.close(); }); // backdrop
$("#palette-open").addEventListener("click", () => openPalette());
// Ctrl-k (⌘K on a Mac) works everywhere but the terminal, even while typing.
document.addEventListener("keydown", (e) => {
  if (!(e.ctrlKey || e.metaKey) || e.altKey || e.shiftKey || e.key.toLowerCase() !== "k" || e.target.closest?.(".xterm")) return;
  const d = openDialog();
  if (d && d.id !== "palette") return;
  e.preventDefault();
  e.stopPropagation();
  d ? d.close() : openPalette();
}, true);

document.addEventListener("keydown", (e) => {
  if (e.metaKey || e.altKey || e.isComposing) return;
  const target = e.target;

  // Insert mode: only Esc (leave) is ours; Ctrl-] is handled by the terminal.
  if (isTyping(target)) {
    if (e.key === "Escape" && !target.closest("dialog")) { target.blur(); setMode(); e.preventDefault(); }
    return;
  }
  if (openDialog()) return; // dialogs handle their own keys (Esc closes)

  let k = e.key;
  if (e.ctrlKey) {
    if (!["d", "u", "f", "b"].includes(k)) return;
    k = `ctrl+${k}`;
  }
  if (k === "Shift" || k === "Control") return;
  // Tab moves between the sections and projects lists; elsewhere it stays native.
  if (k === "Tab" && sidebarList(target)) {
    e.preventDefault();
    keys.count = 0; keys.pending = "";
    sidebarList(target) === SECTIONS ? openProjects() : openSections();
    setMode();
    return;
  }
  // Keyboard users activating a focused control keep the browser's behaviour
  // (except sections, which also close the open todo and leave the list).
  // Enter on a focused Review card approves it, like its Approve chip;
  // on a Draft card it enqueues, like its Enqueue chip.
  const card = k === "Enter" && state.todos.get(target.closest?.("button.todo.s-review, button.todo.s-draft")?.dataset.id);
  if (card && enterKey(card)) {
    e.preventDefault();
    attempt(todoKey)(card, enterKey(card));
    return;
  }
  if ((k === "Enter" || k === " ") && target.closest?.("button, a, summary, input, [role=tab]") && sidebarList(target) !== SECTIONS) return;

  // Counts: 5j, 10G …
  if (/^[0-9]$/.test(k) && !(k === "0" && !keys.count) && !keys.pending) {
    keys.count = keys.count * 10 + Number(k);
    setMode();
    return;
  }
  const n = Math.max(1, keys.count);
  const hadCount = keys.count > 0;
  keys.count = 0;
  if (keys.pending) {
    k = keys.pending + k;
    keys.pending = "";
  } else if (["g", "d"].includes(k)) {
    keys.pending = k;
    setMode();
    return;
  }
  setMode();
  if (!BOUND.test(k)) return; // leave Tab, browser shortcuts etc. alone
  e.preventDefault();
  attempt(handleNormal)(k, n, hadCount);
});

// Sidebar lists: o focuses the sections, p the projects (in the phone menu),
// Tab switches between them. j/k move, Enter opens the focused item, Esc, q
// or l leave the list.
const SECTIONS = ".nav > button[data-view]";
const PROJECTS = "#side-project-list .side-project";
function sidebarList(el) {
  if (el?.matches?.(SECTIONS)) return SECTIONS;
  if (el?.closest?.("#side-project-list")) return PROJECTS;
  return null;
}

function openSections() {
  setMenu(false);
  $(`.nav > button[data-view="${state.view}"]`)?.focus();
}

function openSection(name) {
  closeDetail();
  document.activeElement?.blur();
  showView(name);
  setMode();
}

function sidebarKey(k, n, hadCount) {
  const list = sidebarList(document.activeElement);
  const btns = [...document.querySelectorAll(list)];
  const i = btns.indexOf(document.activeElement);
  const go = (j) => btns[Math.max(0, Math.min(btns.length - 1, j))]?.focus();
  switch (k) {
    case "j": case "ArrowDown": return go(i + n);
    case "k": case "ArrowUp": return go(i - n);
    case "gg": return go(hadCount ? n - 1 : 0);
    case "G": return go(hadCount ? n - 1 : Infinity);
    case "Enter": case " ":
      if (list === SECTIONS) return openSection(document.activeElement.dataset.view);
      break;
    case "Escape": case "q": case "l": document.activeElement.blur(); setMenu(false); setMode(); return;
  }
  return false;
}

async function handleNormal(k, n, hadCount) {
  if (sidebarList(document.activeElement) && sidebarKey(k, n, hadCount) !== false) return;
  // Global keys.
  switch (k) {
    case ":": return openCommandLine();
    case "?": return $("#keys-sheet").showModal();
    case "gt": return showView(VIEWS[(VIEWS.indexOf(state.view) + n) % VIEWS.length]);
    case "gT": return showView(VIEWS[(VIEWS.indexOf(state.view) - n + VIEWS.length * n) % VIEWS.length]);
    case "gb": return showView("board");
    case "gc": return toggleChatPane();
    case "gs": return showView("run");
    case "ga": return showView("activity");
    case "gh": return showView("history");
    case "gf": return showView("files");
    case "p": return openProjects();
    case "[": return desktop.matches && setSideCollapsed(!sideCollapsed());
    case "o": return openSections();
    case "Escape": case "q":
      if (menuOpen()) return setMenu(false);
      if (k === "Escape" && pane.open && paneOverlays()) return toggleChatPane(false);
      if (state.detail) return closeDetail();
      if (k === "Escape" && state.query) return clearSearch();
      return;
    case "y": case "A":
      if (await permKey(k) === false) toast("No permission request waiting");
      return;
    case "n": case "N":
      // n answers "deny" only when a permission request is in view; otherwise next/previous search match.
      if (k === "n" && state.perms.length && (state.detail ? state.perms.some((p) => p.todo_id === state.detail) : !state.query)) return permKey("n");
      if (state.view === "board" && !state.detail) return jumpMatch(k === "n" ? 1 : -1);
      return;
    case "/":
      if (state.view === "board" && !state.detail) return openSearch();
      break;
  }

  // Detail view.
  if (state.detail) {
    const t = state.todos.get(state.detail);
    if (["j", "k", "ctrl+d", "ctrl+u", "ctrl+f", "ctrl+b", "gg", "G"].includes(k)) return scrollBy(scroller(), k, n);
    if (["h", "l"].includes(k)) {
      const panes = ["diff", "log", "chat"];
      state.pane = panes[(panes.indexOf(state.pane) + (k === "l" ? 1 : panes.length - 1)) % panes.length];
      return renderPane();
    }
    if (state.pane === "chat" && k === "i") return todoChat.input.focus();
    if (t && k === "Enter" && enterKey(t)) return todoKey(t, enterKey(t));
    if (t) await todoKey(t, k);
    return;
  }

  switch (state.view) {
    case "board": {
      if (!state.project) return;
      const { lane, row } = keys.cur;
      switch (k) {
        case "j": case "ArrowDown": return moveCursor(lane, keys.active ? row + n : row);
        case "k": case "ArrowUp": return moveCursor(lane, row - n);
        case "h": case "ArrowLeft": return moveCursor(stepLane(lane, -n), row);
        case "l": case "ArrowRight": return moveCursor(stepLane(lane, n), row);
        case "gg": return moveCursor(lane, hadCount ? n - 1 : 0);
        case "G": return moveCursor(lane, hadCount ? n - 1 : Infinity);
        case "w": case "b": {
          const step = k === "w" ? 1 : -1;
          for (let li = lane + step; li >= 0 && li < laneCount(); li += step) {
            if (laneTodos(li).length && !laneSkipped(li)) return moveCursor(li, 0);
          }
          return;
        }
        case "Enter": case "Space": case " ": {
          const t = cursorTodo();
          if (t && k === "Enter" && enterKey(t)) return todoKey(t, enterKey(t));
          if (t) return openDetail(t.id);
          return;
        }
        case "a": return openTodoForm();
      }
      const t = cursorTodo();
      if (t) await todoKey(t, k);
      return;
    }
    case "run": {
      const cur = state.procs.find((p) => p.id === attached);
      switch (k) {
        case "i": case "a": case "Enter": return term.focus();
        case "x": if (cur?.running) { await api("DELETE", `/api/processes/${cur.id}`); toast("Stopping"); } return;
        case "R": return startProc({ kind: "web", preset: "run" });
        case "T": return startProc({ kind: "task", preset: "test" });
        case "D": return startProc({ kind: "task", preset: "deploy" });
        case "!": return startProc({ kind: "pty" });
      }
      return;
    }
    case "activity": case "history":
      if (["j", "k", "ctrl+d", "ctrl+u", "ctrl+f", "ctrl+b", "gg", "G"].includes(k)) return scrollBy(scroller(), k, n);
  }
}

// Forms: Ctrl-Enter adds to the queue, Ctrl-Shift-Enter or Ctrl-S saves a draft.
$("#todo-form").addEventListener("keydown", (e) => {
  if (e.ctrlKey && e.key === "Enter") { e.preventDefault(); $("#todo-sheet").close(e.shiftKey ? "draft" : "queue"); }
  if (e.ctrlKey && e.key.toLowerCase() === "s") { e.preventDefault(); $("#todo-sheet").close("draft"); }
});

